--
-- Name: reject_theme_feature_candidate(uuid, bigint, bigint, text, text); Type: PROCEDURE; Schema: feature; Owner: ktm_curation_command_owner
--

CREATE PROCEDURE feature.reject_theme_feature_candidate(IN p_candidate_id uuid, IN p_expected_candidate_revision bigint, IN p_command_id bigint, IN p_reason_code text, IN p_principal text, OUT o_candidate_id uuid, OUT o_candidate_revision bigint, OUT o_transition_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'provider_sync', 'ops'
    AS $$
DECLARE
  v_candidate feature.theme_feature_candidates%ROWTYPE;
  v_command ops.domain_commands%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'candidate command requires SERIALIZABLE transaction'
      USING ERRCODE = '25001';
  END IF;
  IF NOT pg_has_role(session_user, 'ktm_curation_admin_executor', 'member')
     OR pg_has_role(session_user, 'ktm_curation_provider_executor', 'member') THEN
    RAISE EXCEPTION 'candidate rejection requires the admin executor'
      USING ERRCODE = '42501';
  END IF;
  IF p_expected_candidate_revision IS NULL OR p_expected_candidate_revision < 1 THEN
    RAISE EXCEPTION 'expected candidate revision must be positive'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_theme_candidate_expected_revision';
  END IF;
  IF p_reason_code IS NULL OR p_reason_code <> btrim(p_reason_code)
     OR p_reason_code = '' OR char_length(p_reason_code) > 128 THEN
    RAISE EXCEPTION 'reason_code must be canonical and non-empty'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_theme_candidate_reason_code';
  END IF;
  IF p_principal IS NULL OR p_principal <> btrim(p_principal)
     OR p_principal = '' OR char_length(p_principal) > 200 THEN
    RAISE EXCEPTION 'principal must be canonical and non-empty'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_theme_candidate_principal';
  END IF;

  SELECT command.* INTO STRICT v_command
  FROM ops.domain_commands AS command
  WHERE command.command_id = p_command_id;
  IF v_command.actor <> p_principal
     OR v_command.operation <> 'admin.theme-feature-candidate.reject' THEN
    RAISE EXCEPTION 'domain command does not match candidate rejection'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_theme_candidate_domain_command';
  END IF;

  SELECT candidate.* INTO STRICT v_candidate
  FROM feature.theme_feature_candidates AS candidate
  WHERE candidate.candidate_id = p_candidate_id
  FOR UPDATE;
  IF v_candidate.row_revision <> p_expected_candidate_revision THEN
    RAISE EXCEPTION 'candidate revision mismatch: expected %, current %',
      p_expected_candidate_revision, v_candidate.row_revision
      USING ERRCODE = '23514', CONSTRAINT = 'ck_theme_candidate_expected_revision';
  END IF;
  IF v_candidate.disposition <> 'active'
     OR v_candidate.review_state <> 'open'
     OR NOT v_candidate.eligibility_present THEN
    RAISE EXCEPTION 'only an active open eligible candidate can be rejected'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_theme_candidate_reject_state';
  END IF;

  UPDATE feature.theme_feature_candidates AS candidate
  SET review_state = 'rejected',
      row_revision = candidate.row_revision + 1,
      updated_at = clock_timestamp()
  WHERE candidate.candidate_id = p_candidate_id
  RETURNING candidate.candidate_id, candidate.row_revision
  INTO STRICT o_candidate_id, o_candidate_revision;

  o_transition_id := feature.append_theme_feature_candidate_transition(
    p_candidate_id,
    v_candidate.feature_id,
    v_candidate.feature_id,
    v_candidate.rule_id,
    v_candidate.source_entity_key,
    v_candidate.review_state,
    'rejected',
    v_candidate.eligibility_present,
    v_candidate.eligibility_present,
    v_candidate.disposition,
    v_candidate.disposition,
    NULL,
    'admin_reject',
    o_candidate_revision,
    v_candidate.rule_row_revision,
    v_candidate.rule_input_hash,
    v_candidate.candidate_input_hash,
    NULL,
    NULL,
    v_candidate.source_record_key,
    v_candidate.source_record_hash,
    NULL,
    NULL,
    p_command_id,
    p_principal,
    p_reason_code,
    jsonb_build_object(
      'schema_version', 1,
      'candidate_id', p_candidate_id::text,
      'expected_candidate_revision', p_expected_candidate_revision
    )
  );
END
$$;


ALTER PROCEDURE feature.reject_theme_feature_candidate(IN p_candidate_id uuid, IN p_expected_candidate_revision bigint, IN p_command_id bigint, IN p_reason_code text, IN p_principal text, OUT o_candidate_id uuid, OUT o_candidate_revision bigint, OUT o_transition_id bigint) OWNER TO ktm_curation_command_owner;

--
-- Name: reject_tvn40_append_only_mutation(); Type: FUNCTION; Schema: feature; Owner: ktm_curation_audit_writer
--

CREATE FUNCTION feature.reject_tvn40_append_only_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME
    USING ERRCODE = '42501';
END
$$;


ALTER FUNCTION feature.reject_tvn40_append_only_mutation() OWNER TO ktm_curation_audit_writer;

--
-- Name: reject_tvn40_truncate(); Type: FUNCTION; Schema: feature; Owner: ktm_curation_audit_writer
--

CREATE FUNCTION feature.reject_tvn40_truncate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  RAISE EXCEPTION '% cannot be truncated', TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME
    USING ERRCODE = '42501';
END
$$;


ALTER FUNCTION feature.reject_tvn40_truncate() OWNER TO ktm_curation_audit_writer;

--
-- Name: reject_user_feature_version_mutation(); Type: FUNCTION; Schema: feature; Owner: ktm_feature_state_procedure_owner
--

CREATE FUNCTION feature.reject_user_feature_version_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.origin <> 'user_request' THEN
            RETURN NEW;
        END IF;
        IF NEW.request_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM ops.feature_change_requests AS request
            WHERE request.request_id = NEW.request_id
              AND request.feature_id = NEW.feature_id
              AND request.action = NEW.change_kind
              AND request.state = 'applied'
        ) THEN
            RAISE EXCEPTION 'user feature version needs its applied request binding'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_user_provenance_request';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN
        IF OLD.origin = 'user_request' THEN
            RAISE EXCEPTION 'user feature version receipts are immutable'
                USING ERRCODE = '42501', CONSTRAINT = 'ck_feature_versions_user_request_immutable';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.origin = 'user_request' OR NEW.origin = 'user_request' THEN
        RAISE EXCEPTION 'user feature version receipts are immutable'
            USING ERRCODE = '42501', CONSTRAINT = 'ck_feature_versions_user_request_immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION feature.reject_user_feature_version_mutation() OWNER TO ktm_feature_state_procedure_owner;

--
-- Name: reject_weather_value_mutation(); Type: FUNCTION; Schema: feature; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION feature.reject_weather_value_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
        BEGIN
            IF TG_OP = 'DELETE' AND NOT EXISTS (
                SELECT 1 FROM feature.features AS f WHERE f.feature_id = OLD.feature_id
            ) THEN
                RETURN OLD;
            END IF;
            RAISE EXCEPTION 'feature_weather_values facts are immutable (ADR-089)'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_weather_values_immutable';
        END;
        $$;


ALTER FUNCTION feature.reject_weather_value_mutation() OWNER TO ktm_feature_schema_owner;

--
-- Name: resolve_curation_import_collection_command(text, uuid, uuid, text, text, bigint, text); Type: PROCEDURE; Schema: feature; Owner: ktm_curation_command_owner
--

CREATE PROCEDURE feature.resolve_curation_import_collection_command(IN p_collection_key text, IN p_theme_id uuid, IN p_source_id uuid, IN p_title text, IN p_edition_key text, IN p_command_id bigint, IN p_principal text, OUT o_collection_id uuid, OUT o_collection_revision bigint, OUT o_created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'ops', 'x_extension'
    AS $$
DECLARE
  v_command ops.domain_commands%ROWTYPE;
  v_collection feature.curation_collections%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'curation import command requires SERIALIZABLE transaction'
      USING ERRCODE = '25001';
  END IF;
  IF NOT pg_has_role(session_user, 'ktm_curation_admin_executor', 'member')
     OR pg_has_role(session_user, 'ktm_curation_provider_executor', 'member') THEN
    RAISE EXCEPTION 'curation import command requires the admin executor'
      USING ERRCODE = '42501';
  END IF;
  IF p_principal IS NULL OR p_principal <> btrim(p_principal) OR p_principal = ''
     OR p_collection_key IS NULL OR p_collection_key <> btrim(p_collection_key)
     OR p_collection_key = '' OR p_theme_id IS NULL
     OR p_title IS NULL OR p_title <> btrim(p_title) OR p_title = ''
     OR p_edition_key IS NULL OR p_edition_key <> btrim(p_edition_key) THEN
    RAISE EXCEPTION 'curation import collection input is not canonical'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_import_collection_input';
  END IF;
  SELECT command.* INTO STRICT v_command
  FROM ops.domain_commands AS command WHERE command.command_id = p_command_id
  FOR UPDATE;
  IF v_command.actor <> p_principal
     OR v_command.operation <> 'admin.curation.import'
     OR EXISTS (
       SELECT 1 FROM ops.domain_command_results AS result
       WHERE result.command_id = p_command_id
     ) THEN
    RAISE EXCEPTION 'domain command does not match active curation import'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_import_domain_command';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('kortravelmap:curation-import', 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('curation-catalog-write', 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('curation-collection:' || p_collection_key, 0));
  PERFORM 1 FROM feature.curated_themes AS theme
  WHERE theme.theme_id = p_theme_id AND theme.archived_at IS NULL FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'active curated theme does not exist'
      USING ERRCODE = '23503', CONSTRAINT = 'fk_tvn40_import_active_theme';
  END IF;
  IF p_source_id IS NOT NULL THEN
    PERFORM 1 FROM feature.curated_sources AS source
    WHERE source.source_id = p_source_id AND source.archived_at IS NULL FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'active curated source does not exist'
        USING ERRCODE = '23503', CONSTRAINT = 'fk_tvn40_import_active_source';
    END IF;
  END IF;

  SELECT collection.* INTO v_collection
  FROM feature.curation_collections AS collection
  WHERE collection.collection_key = p_collection_key FOR UPDATE;
  IF FOUND THEN
    IF (v_collection.theme_id, v_collection.source_id, v_collection.title,
        v_collection.edition_key, v_collection.status, v_collection.visibility,
        v_collection.archived_at IS NULL)
       IS DISTINCT FROM
       (p_theme_id, p_source_id, p_title, p_edition_key,
        'published'::text, 'public'::text, true) THEN
      RAISE EXCEPTION 'existing collection differs from immutable import catalog input'
        USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_import_collection_cas';
    END IF;
    o_collection_id := v_collection.collection_id;
    o_collection_revision := v_collection.row_revision;
    o_created := false;
  ELSE
    o_collection_id := x_extension.gen_random_uuid();
    INSERT INTO feature.curation_collections (
      collection_id, collection_key, theme_id, source_id, title, edition_key,
      description, status, visibility, metadata, created_by, updated_by,
      row_revision, updated_at, archived_at
    ) VALUES (
      o_collection_id, p_collection_key, p_theme_id, p_source_id, p_title,
      p_edition_key, NULL, 'published', 'public', '{}'::jsonb,
      p_principal, p_principal, 1, clock_timestamp(), NULL
    ) RETURNING row_revision INTO STRICT o_collection_revision;
    o_created := true;
  END IF;
  INSERT INTO ops.curation_import_collection_effects (
    command_id, collection_id, operation, created
  ) VALUES (p_command_id, o_collection_id, v_command.operation, o_created);
END
$$;


ALTER PROCEDURE feature.resolve_curation_import_collection_command(IN p_collection_key text, IN p_theme_id uuid, IN p_source_id uuid, IN p_title text, IN p_edition_key text, IN p_command_id bigint, IN p_principal text, OUT o_collection_id uuid, OUT o_collection_revision bigint, OUT o_created boolean) OWNER TO ktm_curation_command_owner;

--
-- Name: resolve_manual_provider_dedup_case(uuid, text, text, bigint, bigint, text, text, text, bigint); Type: PROCEDURE; Schema: feature; Owner: ktm_manual_provider_dedup_procedure_owner
--

CREATE PROCEDURE feature.resolve_manual_provider_dedup_case(IN p_case_id uuid, IN p_decision text, IN p_expected_case_fingerprint text, IN p_expected_manual_row_revision bigint, IN p_expected_provider_row_revision bigint, IN p_survivor_feature_id text, IN p_reason text, IN p_actor text, IN p_domain_command_id bigint, OUT o_outcome text, OUT o_resolution_id uuid, OUT o_event_id uuid, OUT o_manual_feature_id text, OUT o_manual_feature_row_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'provider_sync', 'ops', 'x_extension'
    AS $_$
DECLARE
    v_case ops.manual_provider_dedup_cases%ROWTYPE;
    v_manual feature.features%ROWTYPE;
    v_provider feature.features%ROWTYPE;
    v_origin feature.feature_creation_origins%ROWTYPE;
    v_source record;
    v_primary_source_count integer;
    v_command ops.domain_commands%ROWTYPE;
    v_transition_feature_id text;
    v_transition_row_revision bigint;
    v_transition_id bigint;
    v_action text;
    v_payload jsonb;
    v_event_sha256 text;
    v_event_sequence bigint;
    v_occurred_at timestamptz;
BEGIN
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'manual/provider dedup decision requires READ COMMITTED'
            USING ERRCODE = '25001', CONSTRAINT = 'ck_m05_decision_isolation';
    END IF;
    IF session_user <> 'ktm_feature_api_runtime'
       OR NOT pg_has_role(session_user, 'ktm_manual_provider_dedup_admin_executor', 'member')
       OR pg_has_role(session_user, 'ktm_manual_provider_dedup_detector_executor', 'member') THEN
        RAISE EXCEPTION 'manual/provider dedup decision requires the admin-only executor'
            USING ERRCODE = '42501', CONSTRAINT = 'ck_m05_decision_executor';
    END IF;
    IF p_case_id IS NULL
       OR p_decision NOT IN ('kept', 'merged', 'manual_retired')
       OR p_expected_case_fingerprint !~ '^[0-9a-f]{64}$'
       OR p_expected_manual_row_revision IS NULL OR p_expected_manual_row_revision < 1
       OR p_expected_provider_row_revision IS NULL OR p_expected_provider_row_revision < 1
       OR nullif(btrim(p_reason), '') IS NULL
       OR nullif(btrim(p_actor), '') IS NULL
       OR p_domain_command_id IS NULL OR p_domain_command_id < 1
       OR (p_decision = 'merged' AND nullif(btrim(p_survivor_feature_id), '') IS NULL)
       OR (p_decision <> 'merged' AND p_survivor_feature_id IS NOT NULL) THEN
        RAISE EXCEPTION 'manual/provider dedup decision input is not canonical'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_m05_decision_input';
    END IF;
    SELECT command.* INTO v_command
    FROM ops.domain_commands AS command
    WHERE command.command_id = p_domain_command_id
    FOR SHARE;
    IF NOT FOUND
       OR v_command.actor <> p_actor
       OR v_command.operation <> 'admin.manual-provider-dedup-case.resolve.v1'
       OR EXISTS (
           SELECT 1 FROM ops.domain_command_results AS result
           WHERE result.command_id = p_domain_command_id
       ) THEN
        RAISE EXCEPTION 'manual/provider dedup decision command is not open'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_m05_decision_command';
    END IF;

    -- A sequence is allocated only while this fence is held.  Thus its commit
    -- visibility order is the same as the reconciliation action order.
    PERFORM pg_advisory_xact_lock(hashtextextended('feature-curation-m05', 0));
    SELECT candidate.* INTO v_case
    FROM ops.manual_provider_dedup_cases AS candidate
    WHERE candidate.case_id = p_case_id
    FOR UPDATE;
    IF NOT FOUND
       OR EXISTS (
           SELECT 1 FROM ops.manual_provider_dedup_resolutions AS resolution
           WHERE resolution.case_id = p_case_id
       )
       OR v_case.evidence_fingerprint <> p_expected_case_fingerprint
       OR v_case.manual_feature_row_revision <> p_expected_manual_row_revision
       OR v_case.provider_feature_row_revision <> p_expected_provider_row_revision THEN
        o_outcome := 'stale';
        RETURN;
    END IF;

    PERFORM 1
    FROM feature.features AS locked
    WHERE locked.feature_uuid IN (v_case.manual_feature_uuid, v_case.provider_feature_uuid)
    ORDER BY locked.feature_uuid
    FOR UPDATE;
    SELECT * INTO v_manual
    FROM feature.features
    WHERE feature_id = v_case.manual_feature_id
      AND feature_uuid = v_case.manual_feature_uuid
    FOR UPDATE;
    SELECT * INTO v_provider
    FROM feature.features
    WHERE feature_id = v_case.provider_feature_id
      AND feature_uuid = v_case.provider_feature_uuid
    FOR UPDATE;
    IF NOT FOUND
       OR v_manual.row_revision <> v_case.manual_feature_row_revision
       OR v_provider.row_revision <> v_case.provider_feature_row_revision
       OR v_manual.lifecycle_state <> 'active' OR v_manual.publication_state <> 'published'
       OR v_manual.quality_state <> 'valid' OR v_provider.lifecycle_state <> 'active'
       OR v_provider.publication_state <> 'published' OR v_provider.quality_state <> 'valid'
       OR v_manual.coord IS NULL OR v_provider.coord IS NULL THEN
        o_outcome := 'stale';
        RETURN;
    END IF;
    SELECT origin.* INTO v_origin
    FROM feature.feature_creation_origins AS origin
    WHERE origin.feature_id = v_manual.feature_uuid
      AND origin.creation_command_id = v_case.manual_creation_command_id
      AND origin.origin_kind IN ('manual_admin', 'manual_curation', 'manual_request');
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM feature.manual_feature_identity_claims AS claim
        WHERE claim.feature_id = v_manual.feature_uuid
          AND claim.claimed_by_command_id = v_origin.creation_command_id
    ) THEN
        o_outcome := 'stale';
        RETURN;
    END IF;
    SELECT count(*) INTO v_primary_source_count
    FROM provider_sync.source_links AS link
    JOIN provider_sync.source_entities AS entity
      ON entity.source_entity_key = link.source_entity_key
    JOIN provider_sync.source_entity_heads AS head
      ON head.source_entity_key = entity.source_entity_key
    JOIN provider_sync.source_records AS source
      ON source.source_entity_key = head.source_entity_key
     AND source.source_record_key = head.current_source_record_key
    WHERE link.feature_id = v_provider.feature_id
      AND link.source_role = 'primary';
    IF v_primary_source_count <> 1 THEN
        o_outcome := 'stale';
        RETURN;
    END IF;
    SELECT entity.provider_dataset_id, link.source_entity_key,
           head.current_source_record_key AS source_record_key,
           source.raw_payload_hash, head.observed_at
    INTO v_source
    FROM provider_sync.source_links AS link
    JOIN provider_sync.source_entities AS entity
      ON entity.source_entity_key = link.source_entity_key
    JOIN provider_sync.source_entity_heads AS head
      ON head.source_entity_key = entity.source_entity_key
    JOIN provider_sync.source_records AS source
      ON source.source_entity_key = head.source_entity_key
     AND source.source_record_key = head.current_source_record_key
    WHERE link.feature_id = v_provider.feature_id
      AND link.source_role = 'primary'
    FOR SHARE OF link, entity, head, source;
    IF NOT FOUND
       OR v_source.provider_dataset_id <> v_case.provider_dataset_id
       OR v_source.source_entity_key <> v_case.source_entity_key
       OR v_source.source_record_key <> v_case.source_record_key
       OR v_source.raw_payload_hash <> v_case.source_record_raw_payload_hash
       OR v_source.observed_at <> v_case.source_head_observed_at THEN
        o_outcome := 'stale';
        RETURN;
    END IF;
    IF p_decision = 'merged' AND p_survivor_feature_id <> v_provider.feature_id THEN
        o_outcome := 'stale';
        RETURN;
    END IF;

    INSERT INTO ops.manual_provider_dedup_resolutions (
        case_id, decision, command_id, actor, reason
    ) VALUES (
        v_case.case_id, p_decision, p_domain_command_id, p_actor, btrim(p_reason)
    ) RETURNING resolution_id INTO o_resolution_id;
    o_manual_feature_id := v_manual.feature_id;
    IF p_decision = 'kept' THEN
        o_outcome := 'kept';
        o_manual_feature_row_revision := v_manual.row_revision;
        RETURN;
    END IF;

    CALL feature.transition_admin_feature_state(
        v_manual.feature_id, NULL, NULL, NULL, v_manual.row_revision,
        'manual-provider-dedup', p_actor, 'retire',
        v_transition_feature_id, v_transition_row_revision, v_transition_id
    );
    IF v_transition_feature_id <> v_manual.feature_id
       OR v_transition_row_revision <> v_manual.row_revision + 1
       OR v_transition_id IS NULL THEN
        RAISE EXCEPTION 'manual/provider dedup retirement transition is inconsistent'
            USING ERRCODE = '55000';
    END IF;
    v_action := CASE WHEN p_decision = 'merged' THEN 'rebind' ELSE 'detach' END;
    o_event_id := x_extension.gen_random_uuid();
    SELECT nextval(pg_get_serial_sequence(
        'ops.feature_reference_reconciliation_events', 'event_sequence'
    )) INTO v_event_sequence;
    v_occurred_at := clock_timestamp();
    v_payload := jsonb_build_object(
        'payload_schema_version', 1,
        'event_id', o_event_id,
        'event_sequence', v_event_sequence,
        'occurred_at', to_char(
            v_occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        ),
        'case_id', v_case.case_id,
        'resolution_id', o_resolution_id,
        'action', v_action,
        'old_feature', jsonb_build_object(
            'feature_id', v_manual.feature_id,
            'feature_uuid', v_manual.feature_uuid,
            'row_revision', v_manual.row_revision
        ),
        'replacement_feature', CASE WHEN v_action = 'rebind' THEN jsonb_build_object(
            'feature_id', v_provider.feature_id,
            'feature_uuid', v_provider.feature_uuid,
            'row_revision', v_provider.row_revision
        ) ELSE NULL END,
        'manual_retire_transition_id', v_transition_id,
        'manual_retire_row_revision_after_transition', v_transition_row_revision,
        'command_id', p_domain_command_id
    );
    v_event_sha256 := encode(
        x_extension.digest(convert_to(v_payload::text, 'UTF8'), 'sha256'), 'hex'
    );
    INSERT INTO ops.feature_reference_reconciliation_events (
        event_id, event_sequence, case_id, resolution_id, action,
        old_feature_id, old_feature_uuid, old_feature_row_revision_before_transition,
        replacement_feature_id, replacement_feature_uuid, replacement_feature_row_revision,
        manual_retire_transition_id, manual_retire_row_revision_after_transition,
        command_id, payload_schema_version, event_payload, event_sha256, occurred_at
    ) OVERRIDING SYSTEM VALUE VALUES (
        o_event_id, v_event_sequence, v_case.case_id, o_resolution_id, v_action,
        v_manual.feature_id, v_manual.feature_uuid, v_manual.row_revision,
        CASE WHEN v_action = 'rebind' THEN v_provider.feature_id END,
        CASE WHEN v_action = 'rebind' THEN v_provider.feature_uuid END,
        CASE WHEN v_action = 'rebind' THEN v_provider.row_revision END,
        v_transition_id, v_transition_row_revision, p_domain_command_id,
        1, v_payload, v_event_sha256, v_occurred_at
    );
    o_manual_feature_row_revision := v_transition_row_revision;
    o_outcome := p_decision;
END
$_$;


ALTER PROCEDURE feature.resolve_manual_provider_dedup_case(IN p_case_id uuid, IN p_decision text, IN p_expected_case_fingerprint text, IN p_expected_manual_row_revision bigint, IN p_expected_provider_row_revision bigint, IN p_survivor_feature_id text, IN p_reason text, IN p_actor text, IN p_domain_command_id bigint, OUT o_outcome text, OUT o_resolution_id uuid, OUT o_event_id uuid, OUT o_manual_feature_id text, OUT o_manual_feature_row_revision bigint) OWNER TO ktm_manual_provider_dedup_procedure_owner;

--
-- Name: resolve_manual_provider_dedup_case_v2(uuid, text, text, bigint, bigint, text, text, text, bigint); Type: PROCEDURE; Schema: feature; Owner: ktm_manual_provider_dedup_procedure_owner
--

CREATE PROCEDURE feature.resolve_manual_provider_dedup_case_v2(IN p_case_id uuid, IN p_decision text, IN p_expected_case_fingerprint text, IN p_expected_manual_row_revision bigint, IN p_expected_provider_row_revision bigint, IN p_survivor_feature_id text, IN p_reason text, IN p_actor text, IN p_domain_command_id bigint, OUT o_outcome text, OUT o_resolution_id uuid, OUT o_event_id uuid, OUT o_manual_feature_id text, OUT o_manual_feature_row_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'ops'
    AS $$
BEGIN
    -- An immutable cursor-zero subscription is the paired-consumer activation
    -- receipt. No M05 resolution (including "kept") can predate it.
    PERFORM 1
    FROM ops.feature_reference_reconciliation_subscriptions AS subscription
    JOIN ops.feature_reference_reconciliation_leases AS lease
      ON lease.principal_id = subscription.principal_id
    WHERE subscription.principal_id = 'service:feature-reference-reconciliation'
      AND subscription.initial_event_sequence = 0
      AND subscription.read_scope = 'feature-reference-reconciliation:read'
      AND subscription.ack_scope = 'feature-reference-reconciliation:ack'
      AND lease.acked_through_sequence >= 0
    FOR SHARE OF subscription, lease;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'feature reference reconciliation subscription is not provisioned'
            USING ERRCODE = 'P0002';
    END IF;
    CALL feature.resolve_manual_provider_dedup_case(
        p_case_id, p_decision, p_expected_case_fingerprint,
        p_expected_manual_row_revision, p_expected_provider_row_revision,
        p_survivor_feature_id, p_reason, p_actor, p_domain_command_id,
        o_outcome, o_resolution_id, o_event_id, o_manual_feature_id,
        o_manual_feature_row_revision
    );
END
$$;


ALTER PROCEDURE feature.resolve_manual_provider_dedup_case_v2(IN p_case_id uuid, IN p_decision text, IN p_expected_case_fingerprint text, IN p_expected_manual_row_revision bigint, IN p_expected_provider_row_revision bigint, IN p_survivor_feature_id text, IN p_reason text, IN p_actor text, IN p_domain_command_id bigint, OUT o_outcome text, OUT o_resolution_id uuid, OUT o_event_id uuid, OUT o_manual_feature_id text, OUT o_manual_feature_row_revision bigint) OWNER TO ktm_manual_provider_dedup_procedure_owner;

--
-- Name: revoke_feature_field_overrides(text, bigint, text, text, bigint, text[]); Type: PROCEDURE; Schema: feature; Owner: ktm_feature_state_procedure_owner
--

CREATE PROCEDURE feature.revoke_feature_field_overrides(IN p_feature_id text, IN p_expected_row_revision bigint, IN p_principal text, IN p_reason_code text, IN p_command_id bigint, IN p_field_paths text[], OUT o_feature_id text, OUT o_row_revision bigint, OUT o_command_id bigint, OUT o_applied_field_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_feature feature.features%ROWTYPE;
    v_registry ops.feature_override_field_paths%ROWTYPE;
    v_operation text;
    v_field_path text;
    v_values jsonb;
    v_geometry_wkt jsonb;
BEGIN
    IF p_expected_row_revision IS NULL OR p_expected_row_revision < 1
       OR p_command_id IS NULL
       OR coalesce(btrim(p_feature_id), '') = ''
       OR coalesce(btrim(p_principal), '') = ''
       OR coalesce(btrim(p_reason_code), '') = ''
       OR p_field_paths IS NULL OR cardinality(p_field_paths) < 1
       OR EXISTS (SELECT 1 FROM unnest(p_field_paths) AS path WHERE coalesce(btrim(path), '') = '')
       OR cardinality(p_field_paths) <> (SELECT count(DISTINCT path) FROM unnest(p_field_paths) AS path) THEN
        RAISE EXCEPTION 'field override revoke has invalid arguments'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_command';
    END IF;
    o_applied_field_count := cardinality(p_field_paths);

    SELECT command.operation INTO v_operation
    FROM ops.domain_commands AS command
    WHERE command.command_id = p_command_id
      AND command.actor = btrim(p_principal)
      AND NOT EXISTS (
          SELECT 1 FROM ops.domain_command_results AS result
          WHERE result.command_id = command.command_id
      )
    FOR SHARE;
    IF NOT FOUND OR v_operation <> 'admin.feature.override.revoke' THEN
        RAISE EXCEPTION 'field override revoke requires an open matching domain command'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_command';
    END IF;

    SELECT * INTO v_feature FROM feature.features
    WHERE feature_id = p_feature_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'feature % does not exist', p_feature_id USING ERRCODE = 'P0002';
    END IF;
    IF v_feature.row_revision <> p_expected_row_revision THEN
        RAISE EXCEPTION 'feature % revision changed', p_feature_id USING ERRCODE = '40001';
    END IF;

    FOREACH v_field_path IN ARRAY p_field_paths LOOP
        SELECT * INTO v_registry FROM ops.feature_override_field_paths
        WHERE field_path = v_field_path;
        IF NOT FOUND OR (v_registry.feature_kind <> '*' AND v_registry.feature_kind <> v_feature.kind) THEN
            RAISE EXCEPTION 'operator cannot revoke field path %', v_field_path
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_field_path';
        END IF;
        PERFORM 1 FROM ops.feature_overrides
        WHERE feature_id = p_feature_id AND field_path = v_field_path AND status = 'active'
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Feature has no active field override for %', v_field_path
                USING ERRCODE = 'P0002';
        END IF;
        PERFORM 1 FROM feature.feature_base_field_values
        WHERE feature_id = p_feature_id AND field_path = v_field_path
        FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'field override % has no provider base to restore', v_field_path
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_revoke_base';
        END IF;
    END LOOP;

    SELECT COALESCE(jsonb_object_agg(base.field_path, base.value_json)
                    FILTER (WHERE registry.value_kind <> 'geometry'), '{}'::jsonb),
           COALESCE(jsonb_object_agg(
                    base.field_path,
                    CASE WHEN base.value_json = 'null'::jsonb THEN 'null'::jsonb
                         ELSE to_jsonb(x_extension.st_astext(base.value_geometry)) END
                ) FILTER (WHERE registry.value_kind = 'geometry'), '{}'::jsonb)
    INTO v_values, v_geometry_wkt
    FROM feature.feature_base_field_values AS base
    JOIN ops.feature_override_field_paths AS registry USING (field_path)
    WHERE base.feature_id = p_feature_id AND base.field_path = ANY(p_field_paths);

    UPDATE ops.feature_overrides
    SET status = 'revoked', revoked_at = clock_timestamp(),
        revoked_by = btrim(p_principal), revoked_reason = btrim(p_reason_code)
    WHERE feature_id = p_feature_id AND field_path = ANY(p_field_paths) AND status = 'active';

    UPDATE feature.features AS core
    SET name = CASE
            WHEN v_values ? 'core.name'
            THEN v_values ->> 'core.name'
            ELSE core.name
        END,
        category = CASE
            WHEN v_values ? 'core.category'
            THEN v_values ->> 'core.category'
            ELSE core.category
        END,
        coord = CASE
            WHEN v_geometry_wkt ? 'core.coord'
            THEN CASE WHEN v_geometry_wkt ->> 'core.coord' IS NULL THEN NULL ELSE x_extension.st_geomfromtext(v_geometry_wkt ->> 'core.coord', 4326) END
            ELSE core.coord
        END,
        coord_precision_digits = CASE
            WHEN v_values ? 'core.coord_precision_digits'
            THEN (v_values ->> 'core.coord_precision_digits')::smallint
            ELSE core.coord_precision_digits
        END,
        address = CASE
            WHEN v_values ? 'core.address'
            THEN v_values -> 'core.address'
            ELSE core.address
        END,
        legal_dong_code = CASE
            WHEN v_values ? 'core.legal_dong_code'
            THEN v_values ->> 'core.legal_dong_code'
            ELSE core.legal_dong_code
        END,
        road_name_code = CASE
            WHEN v_values ? 'core.road_name_code'
            THEN v_values ->> 'core.road_name_code'
            ELSE core.road_name_code
        END,
        road_address_management_no = CASE
            WHEN v_values ? 'core.road_address_management_no'
            THEN v_values ->> 'core.road_address_management_no'
            ELSE core.road_address_management_no
        END,
        admin_dong_code = CASE
            WHEN v_values ? 'core.admin_dong_code'
            THEN v_values ->> 'core.admin_dong_code'
            ELSE core.admin_dong_code
        END,
        sido_code = CASE
            WHEN v_values ? 'core.sido_code'
            THEN v_values ->> 'core.sido_code'
            ELSE core.sido_code
        END,
        sigungu_code = CASE
            WHEN v_values ? 'core.sigungu_code'
            THEN v_values ->> 'core.sigungu_code'
            ELSE core.sigungu_code
        END,
        urls = CASE
            WHEN v_values ? 'core.urls'
            THEN v_values -> 'core.urls'
            ELSE core.urls
        END,
        marker_icon = CASE
            WHEN v_values ? 'core.marker_icon'
            THEN v_values ->> 'core.marker_icon'
            ELSE core.marker_icon
        END,
        marker_color = CASE
            WHEN v_values ? 'core.marker_color'
            THEN v_values ->> 'core.marker_color'
            ELSE core.marker_color
        END,
        parent_feature_id = CASE
            WHEN v_values ? 'core.parent_feature_id'
            THEN v_values ->> 'core.parent_feature_id'
            ELSE core.parent_feature_id
        END,
        sibling_group_id = CASE
            WHEN v_values ? 'core.sibling_group_id'
            THEN NULLIF(v_values ->> 'core.sibling_group_id', '')::uuid
            ELSE core.sibling_group_id
        END,
        raw_refs = CASE
            WHEN v_values ? 'core.raw_refs'
            THEN v_values -> 'core.raw_refs'
            ELSE core.raw_refs
        END,
        updated_at = clock_timestamp()
    WHERE core.feature_id = p_feature_id
    RETURNING core.feature_id, core.row_revision INTO o_feature_id, o_row_revision;
    IF v_feature.kind = 'place' AND EXISTS (SELECT 1 FROM jsonb_object_keys(v_values) AS supplied_path(field_path) WHERE supplied_path.field_path LIKE 'place.%') THEN
        PERFORM 1 FROM feature.feature_places WHERE feature_id = p_feature_id FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'place subtype is missing'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_subtype';
        END IF;
        UPDATE feature.feature_places AS place
        SET place_kind = CASE
            WHEN v_values ? 'place.place_kind'
            THEN v_values ->> 'place.place_kind'
            ELSE place.place_kind
        END,
            phones = CASE
            WHEN v_values ? 'place.phones'
            THEN ARRAY(SELECT jsonb_array_elements_text(v_values -> 'place.phones'))
            ELSE place.phones
        END,
            biz_number = CASE
            WHEN v_values ? 'place.biz_number'
            THEN v_values ->> 'place.biz_number'
            ELSE place.biz_number
        END,
            license_date = CASE
            WHEN v_values ? 'place.license_date'
            THEN (v_values ->> 'place.license_date')::date
            ELSE place.license_date
        END,
            business_hours = CASE
            WHEN v_values ? 'place.business_hours'
            THEN v_values -> 'place.business_hours'
            ELSE place.business_hours
        END,
            facility_info = CASE
            WHEN v_values ? 'place.facility_info'
            THEN v_values -> 'place.facility_info'
            ELSE place.facility_info
        END,
            reviews_link = CASE
            WHEN v_values ? 'place.reviews_link'
            THEN v_values -> 'place.reviews_link'
            ELSE place.reviews_link
        END,
            payload = CASE
            WHEN v_values ? 'place.payload'
            THEN v_values -> 'place.payload'
            ELSE place.payload
        END
      WHERE place.feature_id = p_feature_id;
    ELSIF v_feature.kind = 'event' AND EXISTS (SELECT 1 FROM jsonb_object_keys(v_values) AS supplied_path(field_path) WHERE supplied_path.field_path LIKE 'event.%') THEN
        PERFORM 1 FROM feature.feature_events WHERE feature_id = p_feature_id FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'event subtype is missing'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_subtype';
        END IF;
        UPDATE feature.feature_events AS event
        SET event_kind = CASE
            WHEN v_values ? 'event.event_kind'
            THEN v_values ->> 'event.event_kind'
            ELSE event.event_kind
        END,
            starts_on = CASE
            WHEN v_values ? 'event.starts_on'
            THEN (v_values ->> 'event.starts_on')::date
            ELSE event.starts_on
        END,
            ends_on = CASE
            WHEN v_values ? 'event.ends_on'
            THEN (v_values ->> 'event.ends_on')::date
            ELSE event.ends_on
        END,
            timezone = CASE
            WHEN v_values ? 'event.timezone'
            THEN v_values ->> 'event.timezone'
            ELSE event.timezone
        END,
            opening_hours = CASE
            WHEN v_values ? 'event.opening_hours'
            THEN v_values -> 'event.opening_hours'
            ELSE event.opening_hours
        END,
            venue_name = CASE
            WHEN v_values ? 'event.venue_name'
            THEN v_values ->> 'event.venue_name'
            ELSE event.venue_name
        END,
            tel = CASE
            WHEN v_values ? 'event.tel'
            THEN v_values ->> 'event.tel'
            ELSE event.tel
        END,
            content_id = CASE
            WHEN v_values ? 'event.content_id'
            THEN v_values ->> 'event.content_id'
            ELSE event.content_id
        END,
            content_type_id = CASE
            WHEN v_values ? 'event.content_type_id'
            THEN v_values ->> 'event.content_type_id'
            ELSE event.content_type_id
        END,
            area_code = CASE
            WHEN v_values ? 'event.area_code'
            THEN v_values ->> 'event.area_code'
            ELSE event.area_code
        END,
            sigungu_code = CASE
            WHEN v_values ? 'event.sigungu_code'
            THEN v_values ->> 'event.sigungu_code'
            ELSE event.sigungu_code
        END,
            payload = CASE
            WHEN v_values ? 'event.payload'
            THEN v_values -> 'event.payload'
            ELSE event.payload
        END
      WHERE event.feature_id = p_feature_id;
    ELSIF v_feature.kind = 'notice' AND EXISTS (SELECT 1 FROM jsonb_object_keys(v_values) AS supplied_path(field_path) WHERE supplied_path.field_path LIKE 'notice.%') THEN
        PERFORM 1 FROM feature.feature_notices WHERE feature_id = p_feature_id FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'notice subtype is missing'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_subtype';
        END IF;
        UPDATE feature.feature_notices AS notice
        SET notice_type = CASE
            WHEN v_values ? 'notice.notice_type'
            THEN v_values ->> 'notice.notice_type'
            ELSE notice.notice_type
        END,
            severity = CASE
            WHEN v_values ? 'notice.severity'
            THEN (v_values ->> 'notice.severity')::smallint
            ELSE notice.severity
        END,
            valid_start_time = CASE
            WHEN v_values ? 'notice.valid_start_time'
            THEN (v_values ->> 'notice.valid_start_time')::timestamptz
            ELSE notice.valid_start_time
        END,
            valid_end_time = CASE
            WHEN v_values ? 'notice.valid_end_time'
            THEN (v_values ->> 'notice.valid_end_time')::timestamptz
            ELSE notice.valid_end_time
        END,
            source_agency = CASE
            WHEN v_values ? 'notice.source_agency'
            THEN v_values ->> 'notice.source_agency'
            ELSE notice.source_agency
        END,
            officer_name = CASE
            WHEN v_values ? 'notice.officer_name'
            THEN v_values ->> 'notice.officer_name'
            ELSE notice.officer_name
        END,
            payload = CASE
            WHEN v_values ? 'notice.payload'
            THEN v_values -> 'notice.payload'
            ELSE notice.payload
        END
      WHERE notice.feature_id = p_feature_id;
    ELSIF v_feature.kind = 'route' AND (EXISTS (SELECT 1 FROM jsonb_object_keys(v_values) AS supplied_path(field_path) WHERE supplied_path.field_path LIKE 'route.%') OR EXISTS (SELECT 1 FROM jsonb_object_keys(v_geometry_wkt) AS supplied_path(field_path) WHERE supplied_path.field_path LIKE 'route.%')) THEN
        PERFORM 1 FROM feature.feature_routes WHERE feature_id = p_feature_id FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'route subtype is missing'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_subtype';
        END IF;
        UPDATE feature.feature_routes AS route
        SET geom = CASE
            WHEN v_geometry_wkt ? 'route.geom'
            THEN x_extension.st_multi(x_extension.st_geomfromtext(v_geometry_wkt ->> 'route.geom', 4326))
            ELSE route.geom
        END,
            route_type = CASE
            WHEN v_values ? 'route.route_type'
            THEN v_values ->> 'route.route_type'
            ELSE route.route_type
        END,
            geometry_source = CASE
            WHEN v_values ? 'route.geometry_source'
            THEN v_values ->> 'route.geometry_source'
            ELSE route.geometry_source
        END,
            geometry_status = CASE
            WHEN v_values ? 'route.geometry_status'
            THEN v_values ->> 'route.geometry_status'
            ELSE route.geometry_status
        END,
            total_distance_meters = CASE
            WHEN v_values ? 'route.total_distance_meters'
            THEN (v_values ->> 'route.total_distance_meters')::numeric
            ELSE route.total_distance_meters
        END,
            expected_duration_minutes = CASE
            WHEN v_values ? 'route.expected_duration_minutes'
            THEN (v_values ->> 'route.expected_duration_minutes')::integer
            ELSE route.expected_duration_minutes
        END,
            difficulty = CASE
            WHEN v_values ? 'route.difficulty'
            THEN v_values ->> 'route.difficulty'
            ELSE route.difficulty
        END,
            begin_name = CASE
            WHEN v_values ? 'route.begin_name'
            THEN v_values ->> 'route.begin_name'
            ELSE route.begin_name
        END,
            begin_address = CASE
            WHEN v_values ? 'route.begin_address'
            THEN v_values ->> 'route.begin_address'
            ELSE route.begin_address
        END,
            end_name = CASE
            WHEN v_values ? 'route.end_name'
            THEN v_values ->> 'route.end_name'
            ELSE route.end_name
        END,
            end_address = CASE
            WHEN v_values ? 'route.end_address'
            THEN v_values ->> 'route.end_address'
            ELSE route.end_address
        END,
            payload = CASE
            WHEN v_values ? 'route.payload'
            THEN v_values -> 'route.payload'
            ELSE route.payload
        END
      WHERE route.feature_id = p_feature_id;
    ELSIF v_feature.kind = 'area' AND (EXISTS (SELECT 1 FROM jsonb_object_keys(v_values) AS supplied_path(field_path) WHERE supplied_path.field_path LIKE 'area.%') OR EXISTS (SELECT 1 FROM jsonb_object_keys(v_geometry_wkt) AS supplied_path(field_path) WHERE supplied_path.field_path LIKE 'area.%')) THEN
        PERFORM 1 FROM feature.feature_areas WHERE feature_id = p_feature_id FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'area subtype is missing'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_subtype';
        END IF;
        UPDATE feature.feature_areas AS area
        SET geom = CASE
            WHEN v_geometry_wkt ? 'area.geom'
            THEN x_extension.st_multi(x_extension.st_geomfromtext(v_geometry_wkt ->> 'area.geom', 4326))
            ELSE area.geom
        END,
            area_kind = CASE
            WHEN v_values ? 'area.area_kind'
            THEN v_values ->> 'area.area_kind'
            ELSE area.area_kind
        END,
            boundary_source = CASE
            WHEN v_values ? 'area.boundary_source'
            THEN v_values ->> 'area.boundary_source'
            ELSE area.boundary_source
        END,
            area_square_meters = CASE
            WHEN v_values ? 'area.area_square_meters'
            THEN (v_values ->> 'area.area_square_meters')::numeric
            ELSE area.area_square_meters
        END,
            regulation_scope = CASE
            WHEN v_values ? 'area.regulation_scope'
            THEN v_values ->> 'area.regulation_scope'
            ELSE area.regulation_scope
        END,
            administrative_office = CASE
            WHEN v_values ? 'area.administrative_office'
            THEN v_values ->> 'area.administrative_office'
            ELSE area.administrative_office
        END,
            description = CASE
            WHEN v_values ? 'area.description'
            THEN v_values ->> 'area.description'
            ELSE area.description
        END,
            payload = CASE
            WHEN v_values ? 'area.payload'
            THEN v_values -> 'area.payload'
            ELSE area.payload
        END
      WHERE area.feature_id = p_feature_id;
    END IF;
    o_command_id := p_command_id;
END;
$$;


ALTER PROCEDURE feature.revoke_feature_field_overrides(IN p_feature_id text, IN p_expected_row_revision bigint, IN p_principal text, IN p_reason_code text, IN p_command_id bigint, IN p_field_paths text[], OUT o_feature_id text, OUT o_row_revision bigint, OUT o_command_id bigint, OUT o_applied_field_count integer) OWNER TO ktm_feature_state_procedure_owner;

--
-- Name: revoke_lifecycle_override(text, text, bigint); Type: PROCEDURE; Schema: feature; Owner: ktm_feature_state_procedure_owner
--

CREATE PROCEDURE feature.revoke_lifecycle_override(IN p_feature_id text, IN p_principal text, IN p_expected_row_revision bigint, OUT o_row_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_current feature.features%ROWTYPE;
BEGIN
    IF coalesce(btrim(p_principal), '') = ''
       OR p_expected_row_revision IS NULL OR p_expected_row_revision < 1 THEN
        RAISE EXCEPTION 'lifecycle override revoke has invalid typed arguments'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_lifecycle_override_command';
    END IF;

    SELECT * INTO v_current
      FROM feature.features
     WHERE feature_id = p_feature_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'feature % does not exist', p_feature_id USING ERRCODE = 'P0002';
    END IF;
    IF v_current.row_revision <> p_expected_row_revision THEN
        RAISE EXCEPTION 'feature % revision changed', p_feature_id USING ERRCODE = '40001';
    END IF;

    UPDATE ops.feature_overrides
       SET status = 'superseded',
           created_by = btrim(p_principal),
           created_at = clock_timestamp()
     WHERE feature_id = p_feature_id
       AND field_path = 'lifecycle_state'
       AND status = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'feature % has no active lifecycle override', p_feature_id
            USING ERRCODE = 'P0002';
    END IF;
    o_row_revision := v_current.row_revision;
END;
$$;


ALTER PROCEDURE feature.revoke_lifecycle_override(IN p_feature_id text, IN p_principal text, IN p_expected_row_revision bigint, OUT o_row_revision bigint) OWNER TO ktm_feature_state_procedure_owner;

--
-- Name: seal_provider_curation_snapshot_receipt(uuid, bigint, text, text, bigint, text); Type: PROCEDURE; Schema: feature; Owner: ktm_curation_command_owner
--

CREATE PROCEDURE feature.seal_provider_curation_snapshot_receipt(IN p_root_job_id uuid, IN p_provider_dataset_id bigint, IN p_sync_scope text, IN p_operation_key text, IN p_expected_input_member_count bigint, IN p_expected_input_set_hash text, OUT o_source_job_id uuid, OUT o_observed_at timestamp with time zone, OUT o_source_entity_count bigint, OUT o_source_input_set_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'provider_sync', 'ops', 'x_extension'
    AS $_$
DECLARE
  v_child ops.import_jobs%ROWTYPE;
  v_input_member_count bigint;
  v_last_source_modified_at date;
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'provider snapshot seal requires SERIALIZABLE transaction'
      USING ERRCODE = '25001';
  END IF;
  IF NOT pg_has_role(session_user, 'ktm_curation_provider_executor', 'member')
     OR pg_has_role(session_user, 'ktm_curation_admin_executor', 'member') THEN
    RAISE EXCEPTION 'provider snapshot seal requires the provider executor'
      USING ERRCODE = '42501';
  END IF;
  SELECT child.* INTO STRICT v_child
  FROM ops.import_jobs AS child
  JOIN ops.import_job_datasets AS member ON member.job_id = child.job_id
  WHERE child.parent_job_id = p_root_job_id
    AND child.kind = 'provider_feature_load'
    AND child.status IN ('queued','running')
    AND child.cancellation_id IS NULL AND child.quarantined_at IS NULL
    AND member.provider_dataset_id = p_provider_dataset_id
    AND member.sync_scope = p_sync_scope
    AND member.operation_key = p_operation_key
  FOR UPDATE OF child;
  IF NOT EXISTS (
    SELECT 1 FROM ops.import_jobs AS root
    WHERE root.job_id = p_root_job_id
      AND root.kind = 'provider_feature_load_run'
      AND root.status = 'running'
      AND root.dagster_run_status IN ('STARTED','CANCELING')
      AND root.dagster_run_id = v_child.dagster_run_id
      AND root.cancellation_id IS NULL AND root.quarantined_at IS NULL
  ) OR (SELECT count(*) FROM ops.import_job_datasets AS member
        WHERE member.job_id = v_child.job_id) <> 1 THEN
    RAISE EXCEPTION 'provider snapshot seal requires one exact running member'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_provider_snapshot_member';
  END IF;

  PERFORM 1 FROM provider_sync.source_entities AS entity
  WHERE entity.provider_dataset_id = p_provider_dataset_id
  ORDER BY entity.source_entity_key FOR SHARE;
  PERFORM 1
  FROM provider_sync.source_records AS record
  JOIN provider_sync.source_entity_heads AS head
    ON head.source_entity_key = record.source_entity_key
   AND head.current_source_record_key = record.source_record_key
  JOIN provider_sync.source_entities AS entity
    ON entity.source_entity_key = head.source_entity_key
  WHERE entity.provider_dataset_id = p_provider_dataset_id
  ORDER BY record.source_entity_key, record.source_record_key
  FOR SHARE OF record;
  PERFORM 1
  FROM provider_sync.source_entity_heads AS head
  JOIN provider_sync.source_entities AS entity
    ON entity.source_entity_key = head.source_entity_key
  WHERE entity.provider_dataset_id = p_provider_dataset_id
  ORDER BY head.source_entity_key FOR SHARE OF head;

  o_source_job_id := v_child.job_id;
  o_observed_at := clock_timestamp();
  SELECT input.source_entity_count, input.input_member_count,
         input.last_source_modified_at, input.source_input_set_hash
  INTO STRICT o_source_entity_count, v_input_member_count,
       v_last_source_modified_at, o_source_input_set_hash
  FROM feature.current_provider_curation_input_set(p_provider_dataset_id) AS input;
  IF p_expected_input_member_count IS NULL
     OR p_expected_input_set_hash !~ '^[0-9a-f]{64}$'
     OR p_expected_input_member_count <> v_input_member_count
     OR p_expected_input_set_hash <> o_source_input_set_hash THEN
    RAISE EXCEPTION 'provider load input changed before child completion'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_provider_snapshot_load_input';
  END IF;

  INSERT INTO ops.curation_provider_snapshot_receipts (
    source_job_id, root_job_id, provider_dataset_id, sync_scope, operation_key,
    observed_at, source_entity_count, input_member_count,
    last_source_modified_at, source_input_set_hash
  )
  SELECT v_child.job_id, p_root_job_id, p_provider_dataset_id, p_sync_scope,
         p_operation_key, o_observed_at, o_source_entity_count,
         v_input_member_count, v_last_source_modified_at,
         o_source_input_set_hash;
END
$_$;


ALTER PROCEDURE feature.seal_provider_curation_snapshot_receipt(IN p_root_job_id uuid, IN p_provider_dataset_id bigint, IN p_sync_scope text, IN p_operation_key text, IN p_expected_input_member_count bigint, IN p_expected_input_set_hash text, OUT o_source_job_id uuid, OUT o_observed_at timestamp with time zone, OUT o_source_entity_count bigint, OUT o_source_input_set_hash text) OWNER TO ktm_curation_command_owner;

--
-- Name: set_feature_coord_precision(); Type: FUNCTION; Schema: feature; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION feature.set_feature_coord_precision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF NEW.coord IS NULL THEN
                NEW.coord_precision_digits := NULL;
            ELSIF NEW.coord_precision_digits IS NULL THEN
                NEW.coord_precision_digits := 6;
            END IF;
            RETURN NEW;
        END;
        $$;


ALTER FUNCTION feature.set_feature_coord_precision() OWNER TO ktm_feature_schema_owner;

--
-- Name: submit_feature_request(uuid, jsonb, bigint); Type: PROCEDURE; Schema: feature; Owner: ktm_feature_request_procedure_owner
--

CREATE PROCEDURE feature.submit_feature_request(IN p_request_id uuid, IN p_request_payload jsonb, IN p_domain_command_id bigint, OUT o_status text, OUT o_submitted_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'ops', 'x_extension'
    AS $_$
DECLARE
    v_command ops.domain_commands%ROWTYPE;
    v_existing ops.feature_requests%ROWTYPE;
BEGIN
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'Feature request submission requires READ COMMITTED'
            USING ERRCODE = '25001', CONSTRAINT = 'ck_feature_request_isolation';
    END IF;
    IF session_user <> 'ktm_feature_api_runtime'
       OR NOT pg_has_role(session_user, 'ktm_feature_request_service_executor', 'member') THEN
        RAISE EXCEPTION 'Feature request submission requires service executor'
            USING ERRCODE = '42501', CONSTRAINT = 'ck_feature_request_executor';
    END IF;
    SELECT command.* INTO v_command
    FROM ops.domain_commands AS command WHERE command.command_id = p_domain_command_id FOR UPDATE;
    IF NOT FOUND OR v_command.operation <> 'service.feature-request.submit.v1'
       OR btrim(v_command.actor) <> 'service:feature-request'
       OR EXISTS (SELECT 1 FROM ops.domain_command_results AS result WHERE result.command_id = p_domain_command_id) THEN
        RAISE EXCEPTION 'Feature request submission command does not match writer'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_request_command';
    END IF;
    IF p_request_id IS NULL OR jsonb_typeof(p_request_payload) IS DISTINCT FROM 'object'
       OR jsonb_typeof(p_request_payload -> 'kind') IS DISTINCT FROM 'string'
       OR p_request_payload ->> 'kind' NOT IN ('place', 'event')
       OR jsonb_typeof(p_request_payload -> 'name') IS DISTINCT FROM 'string'
       OR nullif(btrim(p_request_payload ->> 'name'), '') IS NULL
       OR char_length(p_request_payload ->> 'name') > 200
       OR jsonb_typeof(p_request_payload -> 'lon') IS DISTINCT FROM 'number'
       OR (p_request_payload ->> 'lon')::numeric NOT BETWEEN 124 AND 132
       OR jsonb_typeof(p_request_payload -> 'lat') IS DISTINCT FROM 'number'
       OR (p_request_payload ->> 'lat')::numeric NOT BETWEEN 33 AND 39.5
       OR jsonb_typeof(p_request_payload -> 'categories') IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_request_payload -> 'categories') > 10
       OR jsonb_path_exists(
            p_request_payload,
            '$.categories[*] ? (@.type() != "string")'
       )
       OR (
            p_request_payload ? 'note'
            AND (
                jsonb_typeof(p_request_payload -> 'note') IS DISTINCT FROM 'string'
                OR char_length(p_request_payload ->> 'note') > 2000
            )
       )
       OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_request_payload) AS key_name(key_name)
                  WHERE key_name NOT IN ('kind', 'name', 'lon', 'lat', 'categories', 'note')) THEN
        RAISE EXCEPTION 'Feature request payload is not canonical'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_requests_payload';
    END IF;
    INSERT INTO ops.feature_requests (request_id, request_payload, submission_command_id)
    VALUES (p_request_id, p_request_payload, p_domain_command_id)
    ON CONFLICT (request_id) DO NOTHING
    RETURNING status, submitted_at INTO o_status, o_submitted_at;
    IF o_status IS NULL THEN
        SELECT request.* INTO v_existing
        FROM ops.feature_requests AS request WHERE request.request_id = p_request_id;
        IF NOT FOUND OR v_existing.request_payload IS DISTINCT FROM p_request_payload THEN
        RAISE EXCEPTION 'Feature request id conflicts with a different payload'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_request_idempotency';
        END IF;
        o_status := v_existing.status;
        o_submitted_at := v_existing.submitted_at;
    END IF;
END
$_$;


ALTER PROCEDURE feature.submit_feature_request(IN p_request_id uuid, IN p_request_payload jsonb, IN p_domain_command_id bigint, OUT o_status text, OUT o_submitted_at timestamp with time zone) OWNER TO ktm_feature_request_procedure_owner;

--
-- Name: sync_concierge_catalog_after_observation(); Type: FUNCTION; Schema: feature; Owner: ktm_curation_command_owner
--

CREATE FUNCTION feature.sync_concierge_catalog_after_observation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'provider_sync', 'ops'
    AS $$
DECLARE
  v_provider_dataset_id bigint;
  v_themes_created bigint;
  v_themes_updated bigint;
  v_rules_created bigint;
  v_rules_updated bigint;
  v_rules_archived bigint;
BEGIN
  SELECT source.provider_dataset_id INTO STRICT v_provider_dataset_id
  FROM feature.curated_sources AS source WHERE source.source_id = NEW.source_id;
  IF EXISTS (
    SELECT 1 FROM provider_sync.provider_datasets AS dataset
    WHERE dataset.provider_dataset_id = v_provider_dataset_id
      AND dataset.provider = 'kor-travel-concierge-youtube'
      AND dataset.dataset_key = 'youtube_place_candidates'
  ) THEN
    CALL feature.sync_concierge_theme_catalog(
      v_provider_dataset_id, NEW.import_job_id,
      v_themes_created, v_themes_updated,
      v_rules_created, v_rules_updated, v_rules_archived
    );
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION feature.sync_concierge_catalog_after_observation() OWNER TO ktm_curation_command_owner;

--
-- Name: sync_concierge_theme_catalog(bigint, uuid); Type: PROCEDURE; Schema: feature; Owner: ktm_curation_command_owner
--

CREATE PROCEDURE feature.sync_concierge_theme_catalog(IN p_provider_dataset_id bigint, IN p_import_job_id uuid, OUT o_themes_created bigint, OUT o_themes_updated bigint, OUT o_rules_created bigint, OUT o_rules_updated bigint, OUT o_rules_archived bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'provider_sync', 'ops', 'x_extension'
    AS $$
DECLARE
  v_source_id uuid;
  v_group record;
  v_theme feature.curated_themes%ROWTYPE;
  v_rule feature.curated_source_rules%ROWTYPE;
  v_generation_id uuid;
  v_observed bigint;
  v_removed bigint;
  v_input_hash text;
  v_replayed boolean;
  v_metadata jsonb;
  v_selector jsonb;
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'concierge catalog sync requires SERIALIZABLE transaction'
      USING ERRCODE = '25001';
  END IF;
  IF current_user <> 'ktm_curation_command_owner'
     OR NOT pg_has_role(session_user, 'ktm_curation_provider_executor', 'member')
     OR pg_has_role(session_user, 'ktm_curation_admin_executor', 'member') THEN
    RAISE EXCEPTION 'concierge catalog sync is an internal provider command'
      USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM ops.curation_provider_snapshot_receipts AS receipt
    JOIN provider_sync.provider_datasets AS dataset
      ON dataset.provider_dataset_id = receipt.provider_dataset_id
    WHERE receipt.source_job_id = p_import_job_id
      AND receipt.provider_dataset_id = p_provider_dataset_id
      AND dataset.provider = 'kor-travel-concierge-youtube'
      AND dataset.dataset_key = 'youtube_place_candidates'
  ) THEN
    o_themes_created := 0;
    o_themes_updated := 0;
    o_rules_created := 0;
    o_rules_updated := 0;
    o_rules_archived := 0;
    RETURN;
  END IF;

  SELECT source.source_id INTO STRICT v_source_id
  FROM feature.curated_sources AS source
  WHERE source.provider_dataset_id = p_provider_dataset_id
    AND source.archived_at IS NULL
  FOR UPDATE;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tvn40_concierge_groups (
    grouping_kind text NOT NULL,
    grouping_id text NOT NULL,
    grouping_title text NOT NULL,
    theme_slug text NOT NULL,
    detail_selector jsonb NOT NULL,
    feature_count bigint NOT NULL,
    PRIMARY KEY (grouping_kind, grouping_id),
    UNIQUE (theme_slug)
  ) ON COMMIT DROP;
  TRUNCATE pg_temp.tvn40_concierge_groups;

  INSERT INTO pg_temp.tvn40_concierge_groups (
    grouping_kind, grouping_id, grouping_title, theme_slug,
    detail_selector, feature_count
  )
  WITH current_features AS (
    SELECT DISTINCT feature.feature_id, place.payload
    FROM provider_sync.source_entities AS entity
    JOIN provider_sync.source_entity_heads AS head
      ON head.source_entity_key = entity.source_entity_key
    JOIN provider_sync.source_records AS record
      ON record.source_entity_key = head.source_entity_key
     AND record.source_record_key = head.current_source_record_key
    JOIN provider_sync.source_links AS link
      ON link.source_entity_key = entity.source_entity_key
    JOIN feature.features AS feature ON feature.feature_id = link.feature_id
    JOIN feature.feature_places AS place ON place.feature_id = feature.feature_id
    WHERE entity.provider_dataset_id = p_provider_dataset_id
      AND feature.lifecycle_state = 'active'
      AND feature.publication_state = 'published'
      AND feature.quality_state = 'valid'
  ), expanded AS (
    SELECT feature_id, 'channel'::text AS grouping_kind,
           payload #>> '{kor_travel_concierge,youtube,channel_id}' AS grouping_id,
           payload #>> '{kor_travel_concierge,youtube,channel_title}' AS grouping_title,
           'concierge-yt-'::text AS slug_prefix,
           ARRAY['payload','kor_travel_concierge','youtube','channel_id']::text[] AS selector_path
    FROM current_features
    UNION ALL
    SELECT feature_id, 'playlist'::text,
           payload #>> '{kor_travel_concierge,youtube,playlist_id}',
           payload #>> '{kor_travel_concierge,youtube,playlist_title}',
           'concierge-pl-'::text,
           ARRAY['payload','kor_travel_concierge','youtube','playlist_id']::text[]
    FROM current_features
  )
  SELECT grouping_kind, grouping_id,
         COALESCE(max(NULLIF(btrim(grouping_title), '')), min(slug_prefix) || grouping_id),
         min(slug_prefix) || grouping_id,
         jsonb_build_object('path', min(selector_path), 'value', grouping_id),
         count(DISTINCT feature_id)::bigint
  FROM expanded
  WHERE NULLIF(btrim(grouping_id), '') IS NOT NULL
  GROUP BY grouping_kind, grouping_id;

  -- Only exact legacy rows produced by the retired synchronizer may acquire
  -- provider ownership.  A manually-created prefix collision remains fatal.
  UPDATE feature.curated_themes AS theme
  SET owner_kind = 'provider_dataset',
      owner_provider_dataset_id = p_provider_dataset_id,
      row_revision = theme.row_revision + 1,
      updated_at = clock_timestamp()
  WHERE theme.owner_kind IS NULL
    AND theme.owner_provider_dataset_id IS NULL
    AND EXISTS (
      SELECT 1 FROM ops.curation_concierge_legacy_owner_manifest AS manifest
      WHERE manifest.entity_kind = 'theme' AND manifest.entity_id = theme.theme_id
        AND manifest.before_row_revision = theme.row_revision
        AND manifest.before_input_hash = encode(x_extension.digest(convert_to(
          jsonb_build_array(theme.theme_id::text, theme.row_revision,
                            theme.theme_slug, theme.metadata)::text,
          'UTF8'), 'sha256'), 'hex')
    );
  UPDATE feature.curated_source_rules AS rule
  SET owner_kind = 'provider_dataset',
      owner_provider_dataset_id = p_provider_dataset_id,
      row_revision = rule.row_revision + 1,
      updated_at = clock_timestamp()
  WHERE rule.owner_kind IS NULL
    AND rule.owner_provider_dataset_id IS NULL
    AND rule.source_id = v_source_id
    AND EXISTS (
      SELECT 1 FROM ops.curation_concierge_legacy_owner_manifest AS manifest
      WHERE manifest.entity_kind = 'rule' AND manifest.entity_id = rule.rule_id
        AND manifest.before_row_revision = rule.row_revision
        AND manifest.before_input_hash = encode(x_extension.digest(convert_to(
          jsonb_build_array(rule.rule_id::text, rule.row_revision,
                            rule.theme_id::text, rule.source_id::text,
                            rule.metadata)::text,
          'UTF8'), 'sha256'), 'hex')
    )
    AND EXISTS (
      SELECT 1 FROM feature.curated_themes AS theme
      WHERE theme.theme_id = rule.theme_id
        AND theme.owner_kind = 'provider_dataset'
        AND theme.owner_provider_dataset_id = p_provider_dataset_id
    );

  o_themes_created := 0;
  o_themes_updated := 0;
  o_rules_created := 0;
  o_rules_updated := 0;
  o_rules_archived := 0;
  FOR v_group IN
    SELECT * FROM pg_temp.tvn40_concierge_groups
    ORDER BY grouping_kind, grouping_id
  LOOP
    v_metadata := jsonb_build_object(
      'concierge_kind', v_group.grouping_kind,
      'concierge_value', v_group.grouping_id,
      'poi_count', v_group.feature_count,
      'seed', 'sync_concierge_themes'
    );
    v_selector := v_group.detail_selector;
    SELECT theme.* INTO v_theme
    FROM feature.curated_themes AS theme
    WHERE theme.theme_slug = v_group.theme_slug
    FOR UPDATE;
    IF NOT FOUND THEN
      INSERT INTO feature.curated_themes (
        theme_slug, theme_name, theme_description, theme_group,
        default_curated, visibility, metadata, row_revision, archived_at,
        owner_kind, owner_provider_dataset_id, updated_at
      ) VALUES (
        v_group.theme_slug, v_group.grouping_title, '', 'media', false, 'public',
        v_metadata, 1, NULL, 'provider_dataset', p_provider_dataset_id,
        clock_timestamp()
      ) RETURNING * INTO STRICT v_theme;
      o_themes_created := o_themes_created + 1;
    ELSE
      IF v_theme.owner_kind IS DISTINCT FROM 'provider_dataset'
         OR v_theme.owner_provider_dataset_id IS DISTINCT FROM p_provider_dataset_id THEN
        RAISE EXCEPTION 'concierge theme slug collides with another owner: %', v_group.theme_slug
          USING ERRCODE = '23505', CONSTRAINT = 'uq_tvn40_concierge_theme_owner';
      END IF;
      IF (v_theme.theme_name, v_theme.theme_group, v_theme.visibility,
          v_theme.metadata, v_theme.archived_at IS NULL)
         IS DISTINCT FROM
         (v_group.grouping_title, 'media'::text, 'public'::text,
          v_metadata, true) THEN
        UPDATE feature.curated_themes AS theme
        SET theme_name = v_group.grouping_title,
            theme_group = 'media', visibility = 'public', metadata = v_metadata,
            archived_at = NULL, row_revision = theme.row_revision + 1,
            updated_at = clock_timestamp()
        WHERE theme.theme_id = v_theme.theme_id
        RETURNING * INTO STRICT v_theme;
        o_themes_updated := o_themes_updated + 1;
      END IF;
    END IF;

    IF (SELECT count(*) FROM feature.curated_source_rules AS rule
        WHERE rule.theme_id = v_theme.theme_id AND rule.source_id = v_source_id) > 1 THEN
      RAISE EXCEPTION 'concierge theme has ambiguous source rules: %', v_theme.theme_id
        USING ERRCODE = '23505', CONSTRAINT = 'uq_tvn40_concierge_theme_rule';
    END IF;
    SELECT rule.* INTO v_rule
    FROM feature.curated_source_rules AS rule
    WHERE rule.theme_id = v_theme.theme_id AND rule.source_id = v_source_id
    FOR UPDATE;
    IF NOT FOUND THEN
      INSERT INTO feature.curated_source_rules (
        theme_id, source_id, place_kind, category, region_scope,
        detail_selector, default_action, priority, enabled, metadata,
        row_revision, archived_at, owner_kind, owner_provider_dataset_id, updated_at
      ) VALUES (
        v_theme.theme_id, v_source_id, 'youtube_place_candidate', NULL, '{}'::jsonb,
        v_selector, 'candidate',
        LEAST(v_group.feature_count, 2147483647)::integer, true,
        jsonb_build_object('curation_relation', 'theme_area_anchor'),
        1, NULL, 'provider_dataset', p_provider_dataset_id, clock_timestamp()
      ) RETURNING * INTO STRICT v_rule;
      o_rules_created := o_rules_created + 1;
    ELSE
      IF v_rule.owner_kind IS DISTINCT FROM 'provider_dataset'
         OR v_rule.owner_provider_dataset_id IS DISTINCT FROM p_provider_dataset_id THEN
        RAISE EXCEPTION 'concierge rule collides with another owner: %', v_rule.rule_id
          USING ERRCODE = '23505', CONSTRAINT = 'uq_tvn40_concierge_rule_owner';
      END IF;
      IF (v_rule.place_kind, v_rule.category, v_rule.region_scope,
          v_rule.detail_selector, v_rule.default_action, v_rule.priority,
          v_rule.enabled, v_rule.archived_at IS NULL)
         IS DISTINCT FROM
         ('youtube_place_candidate'::text, NULL::text, '{}'::jsonb,
          v_selector, 'candidate'::text,
          LEAST(v_group.feature_count, 2147483647)::integer,
          true, true) THEN
        UPDATE feature.curated_source_rules AS rule
        SET place_kind = 'youtube_place_candidate', category = NULL,
            region_scope = '{}'::jsonb, detail_selector = v_selector,
            default_action = 'candidate',
            priority = LEAST(v_group.feature_count, 2147483647)::integer,
            enabled = true, archived_at = NULL,
            row_revision = rule.row_revision + 1, updated_at = clock_timestamp()
        WHERE rule.rule_id = v_rule.rule_id;
        o_rules_updated := o_rules_updated + 1;
      END IF;
    END IF;
  END LOOP;

  -- Removed authoritative groups first materialize an empty expected set so
  -- candidate eligibility is audited before their catalog rows are archived.
  FOR v_rule IN
    SELECT rule.*
    FROM feature.curated_source_rules AS rule
    JOIN feature.curated_themes AS theme ON theme.theme_id = rule.theme_id
    WHERE rule.source_id = v_source_id
      AND rule.owner_kind = 'provider_dataset'
      AND rule.owner_provider_dataset_id = p_provider_dataset_id
      AND rule.archived_at IS NULL
      AND theme.owner_kind = 'provider_dataset'
      AND theme.owner_provider_dataset_id = p_provider_dataset_id
      AND NOT EXISTS (
        SELECT 1 FROM pg_temp.tvn40_concierge_groups AS desired
        WHERE desired.theme_slug = theme.theme_slug
      )
    ORDER BY rule.rule_id
  LOOP
    CALL feature.materialize_theme_candidate_generation(
      v_rule.rule_id, 'provider_full_snapshot', p_import_job_id,
      NULL, NULL, NULL, jsonb_build_object(
        'schema_version', 1, 'reason_code', 'catalog_archived'
      ), v_generation_id, v_observed, v_removed, v_input_hash, v_replayed
    );
    UPDATE feature.curated_source_rules AS rule
    SET enabled = false, archived_at = clock_timestamp(),
        row_revision = rule.row_revision + 1, updated_at = clock_timestamp()
    WHERE rule.rule_id = v_rule.rule_id;
    o_rules_archived := o_rules_archived + 1;
  END LOOP;
  UPDATE feature.curated_themes AS theme
  SET archived_at = clock_timestamp(), row_revision = theme.row_revision + 1,
      updated_at = clock_timestamp()
  WHERE theme.owner_kind = 'provider_dataset'
    AND theme.owner_provider_dataset_id = p_provider_dataset_id
    AND theme.archived_at IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM pg_temp.tvn40_concierge_groups AS desired
      WHERE desired.theme_slug = theme.theme_slug
    );
END
$$;


ALTER PROCEDURE feature.sync_concierge_theme_catalog(IN p_provider_dataset_id bigint, IN p_import_job_id uuid, OUT o_themes_created bigint, OUT o_themes_updated bigint, OUT o_rules_created bigint, OUT o_rules_updated bigint, OUT o_rules_archived bigint) OWNER TO ktm_curation_command_owner;

--
-- Name: sync_subtype_public_ready(); Type: FUNCTION; Schema: feature; Owner: ktm_feature_state_procedure_owner
--

CREATE FUNCTION feature.sync_subtype_public_ready() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_public_ready boolean;
BEGIN
    -- The UPDATE which invoked this trigger already holds NEW's parent row
    -- lock.  Keep it until the two subtype cache rows have been refreshed.
    v_public_ready := NEW.lifecycle_state = 'active'
        AND NEW.publication_state = 'published'
        AND NEW.quality_state = 'valid';

    UPDATE feature.feature_routes
       SET public_ready = v_public_ready
     WHERE feature_id = NEW.feature_id
       AND public_ready IS DISTINCT FROM v_public_ready;
    UPDATE feature.feature_areas
       SET public_ready = v_public_ready
     WHERE feature_id = NEW.feature_id
       AND public_ready IS DISTINCT FROM v_public_ready;
    RETURN NULL;
END;
$$;


ALTER FUNCTION feature.sync_subtype_public_ready() OWNER TO ktm_feature_state_procedure_owner;

--
-- Name: touch_curation_import_collection_command(uuid, bigint, text); Type: PROCEDURE; Schema: feature; Owner: ktm_curation_command_owner
--

CREATE PROCEDURE feature.touch_curation_import_collection_command(IN p_collection_id uuid, IN p_command_id bigint, IN p_principal text, OUT o_collection_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature', 'ops'
    AS $$
DECLARE
  v_effect ops.curation_import_collection_effects%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'curation import command requires SERIALIZABLE transaction'
      USING ERRCODE = '25001';
  END IF;
  IF NOT pg_has_role(session_user, 'ktm_curation_admin_executor', 'member')
     OR pg_has_role(session_user, 'ktm_curation_provider_executor', 'member') THEN
    RAISE EXCEPTION 'curation import command requires the admin executor'
      USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM ops.domain_commands AS command
  WHERE command.command_id = p_command_id
    AND command.actor = p_principal
    AND command.operation = 'admin.curation.import'
    AND NOT EXISTS (
      SELECT 1 FROM ops.domain_command_results AS result
      WHERE result.command_id = command.command_id
    ) FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'domain command does not match active curation import'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_import_domain_command';
  END IF;
  SELECT effect.* INTO STRICT v_effect
  FROM ops.curation_import_collection_effects AS effect
  WHERE effect.command_id = p_command_id
    AND effect.collection_id = p_collection_id;
  IF v_effect.created THEN
    SELECT collection.row_revision INTO STRICT o_collection_revision
    FROM feature.curation_collections AS collection
    WHERE collection.collection_id = p_collection_id;
    RETURN;
  END IF;
  INSERT INTO ops.curation_import_collection_touches(command_id, collection_id)
  VALUES (p_command_id, p_collection_id);
  UPDATE feature.curation_collections AS collection
  SET updated_by = p_principal, updated_at = clock_timestamp(),
      row_revision = collection.row_revision + 1
  WHERE collection.collection_id = p_collection_id
  RETURNING collection.row_revision INTO STRICT o_collection_revision;
END
$$;


ALTER PROCEDURE feature.touch_curation_import_collection_command(IN p_collection_id uuid, IN p_command_id bigint, IN p_principal text, OUT o_collection_revision bigint) OWNER TO ktm_curation_command_owner;

--
-- Name: transition_admin_feature_state(text, text, text, text, bigint, text, text, text); Type: PROCEDURE; Schema: feature; Owner: ktm_feature_state_procedure_owner
--

CREATE PROCEDURE feature.transition_admin_feature_state(IN p_feature_id text, IN p_lifecycle_state text, IN p_publication_state text, IN p_quality_state text, IN p_expected_row_revision bigint, IN p_reason_code text, IN p_principal text, IN p_action text, OUT o_feature_id text, OUT o_row_revision bigint, OUT o_transition_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_current feature.features%ROWTYPE;
    v_lifecycle_state text;
    v_publication_state text;
    v_quality_state text;
BEGIN
    IF p_action NOT IN ('patch', 'retire')
       OR p_expected_row_revision IS NULL OR p_expected_row_revision < 1
       OR coalesce(btrim(p_reason_code), '') = ''
       OR coalesce(btrim(p_principal), '') = '' THEN
        RAISE EXCEPTION 'admin state command has invalid arguments'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_admin_state_command';
    END IF;
    SELECT * INTO v_current FROM feature.features
     WHERE feature_id = p_feature_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'feature % does not exist', p_feature_id USING ERRCODE = 'P0002';
    END IF;
    IF v_current.row_revision <> p_expected_row_revision THEN
        RAISE EXCEPTION 'feature % revision changed', p_feature_id USING ERRCODE = '40001';
    END IF;
    IF p_action = 'patch' THEN
        IF p_lifecycle_state IS NOT NULL
           OR (p_publication_state IS NULL AND p_quality_state IS NULL)
           OR (p_publication_state IS NOT NULL
               AND p_publication_state NOT IN ('draft', 'published', 'suppressed'))
           OR (p_quality_state IS NOT NULL
               AND p_quality_state NOT IN ('valid', 'quarantined')) THEN
            RAISE EXCEPTION 'admin state patch may change only publication or quality'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_admin_state_command';
        END IF;
        v_lifecycle_state := v_current.lifecycle_state;
        v_publication_state := coalesce(p_publication_state, v_current.publication_state);
        v_quality_state := coalesce(p_quality_state, v_current.quality_state);
    ELSE
        IF p_lifecycle_state IS NOT NULL
           OR p_publication_state IS NOT NULL
           OR p_quality_state IS NOT NULL THEN
            RAISE EXCEPTION 'retire action derives its complete state tuple'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_admin_state_command';
        END IF;
        v_lifecycle_state := 'retired';
        v_publication_state := 'suppressed';
        v_quality_state := v_current.quality_state;
    END IF;
    CALL feature.transition_feature_state(
        p_feature_id, v_lifecycle_state, v_publication_state, v_quality_state,
        p_expected_row_revision,
        jsonb_build_object(
            'transition_kind', 'admin',
            'reason_code', btrim(p_reason_code),
            'principal', btrim(p_principal)
        ),
        o_feature_id, o_row_revision
    );
    SELECT transition.transition_id INTO o_transition_id
    FROM feature.feature_state_transitions AS transition
    WHERE transition.feature_id = o_feature_id
      AND transition.row_revision = o_row_revision
      AND transition.transition_kind = 'admin'
      AND transition.reason_code = btrim(p_reason_code)
      AND transition.principal = btrim(p_principal)
    ORDER BY transition.transition_id DESC
    LIMIT 1;
    IF o_transition_id IS NULL THEN
        RAISE EXCEPTION 'admin state command did not write its audit transition';
    END IF;
END;
$$;


ALTER PROCEDURE feature.transition_admin_feature_state(IN p_feature_id text, IN p_lifecycle_state text, IN p_publication_state text, IN p_quality_state text, IN p_expected_row_revision bigint, IN p_reason_code text, IN p_principal text, IN p_action text, OUT o_feature_id text, OUT o_row_revision bigint, OUT o_transition_id bigint) OWNER TO ktm_feature_state_procedure_owner;

--
-- Name: transition_feature_state(text, text, text, text, bigint, jsonb); Type: PROCEDURE; Schema: feature; Owner: ktm_feature_state_procedure_owner
--

CREATE PROCEDURE feature.transition_feature_state(IN p_feature_id text, IN p_lifecycle_state text, IN p_publication_state text, IN p_quality_state text, IN p_expected_row_revision bigint, IN p_context jsonb, OUT o_feature_id text, OUT o_row_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_current feature.features%ROWTYPE;
    v_override_row_revision bigint;
BEGIN
    IF p_expected_row_revision IS NULL OR p_expected_row_revision < 1 THEN
        RAISE EXCEPTION 'expected feature row revision is required'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_state_expected_revision';
    END IF;
    PERFORM feature.prepare_feature_state_context(p_context, 'transition');
    -- Provider ingestion locks dataset/entity/record/current-head, then the
    -- Feature source link, then the Feature.  Do the same for every provider
    -- transition. A head advance can therefore either happen before this call
    -- (and reject stale evidence) or after this transition/audit commit,
    -- never between proof and audit.
    IF p_context ->> 'transition_kind' = 'provider_sync' THEN
        PERFORM feature.lock_current_provider_feature_source_evidence(
            p_feature_id,
            (p_context ->> 'provider_dataset_id')::bigint,
            p_context ->> 'source_entity_key',
            p_context ->> 'source_record_key'
        );
    END IF;
    SELECT * INTO v_current
      FROM feature.features
     WHERE feature_id = p_feature_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'feature % does not exist', p_feature_id USING ERRCODE = 'P0002';
    END IF;
    IF v_current.row_revision <> p_expected_row_revision THEN
        RAISE EXCEPTION 'feature % revision changed', p_feature_id USING ERRCODE = '40001';
    END IF;
    IF (v_current.lifecycle_state, v_current.publication_state, v_current.quality_state)
       IS NOT DISTINCT FROM (p_lifecycle_state, p_publication_state, p_quality_state) THEN
        RAISE EXCEPTION 'feature state transition must change at least one axis'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_state_transition_non_noop';
    END IF;
    IF v_current.lifecycle_state = 'retired' AND p_lifecycle_state = 'active' THEN
        IF p_context ->> 'transition_kind' <> 'provider_sync'
           AND (p_context ->> 'transition_kind' NOT IN ('admin', 'user_request', 'system')
           OR coalesce(btrim(p_context ->> 'reactivation_evidence'), '') = '') THEN
            RAISE EXCEPTION 'retired feature may be reactivated only by explicit reingest'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_reactivation_explicit';
        END IF;
        IF EXISTS (
            SELECT 1 FROM ops.feature_overrides AS override
            WHERE override.feature_id = p_feature_id
              AND override.field_path = 'lifecycle_state'
              AND override.status = 'active'
              AND override.override_value = '"retired"'::jsonb
              AND override.prevent_provider_reactivation
        ) AND p_context ->> 'transition_kind' = 'provider_sync' THEN
            RAISE EXCEPTION 'provider reactivation is fenced by lifecycle override'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_provider_reactivation_override';
        END IF;
    END IF;
    UPDATE feature.features
       SET lifecycle_state = p_lifecycle_state,
           publication_state = p_publication_state,
           quality_state = p_quality_state,
           updated_at = clock_timestamp()
     WHERE feature_id = p_feature_id
     RETURNING feature_id, row_revision INTO o_feature_id, o_row_revision;
    -- Any non-provider retirement is not a provider tombstone. Make its
    -- lifecycle override inseparable from the state transition so callers of
    -- this generic internal procedure cannot create a retired row that a
    -- later provider observation can resurrect.
    IF v_current.lifecycle_state = 'active'
       AND p_lifecycle_state = 'retired'
       AND (p_context ->> 'transition_kind') <> 'provider_sync' THEN
        CALL feature.author_lifecycle_override(
            p_feature_id,
            v_current.lifecycle_state,
            'retired',
            true,
            btrim(p_context ->> 'reason_code'),
            btrim(p_context ->> 'principal'),
            o_row_revision,
            v_override_row_revision
        );
        IF v_override_row_revision <> o_row_revision THEN
            RAISE EXCEPTION 'non-provider retirement wrote an inconsistent lifecycle override';
        END IF;
    END IF;
END;
$$;


ALTER PROCEDURE feature.transition_feature_state(IN p_feature_id text, IN p_lifecycle_state text, IN p_publication_state text, IN p_quality_state text, IN p_expected_row_revision bigint, IN p_context jsonb, OUT o_feature_id text, OUT o_row_revision bigint) OWNER TO ktm_feature_state_procedure_owner;

--
-- Name: uuid_generate_v7(); Type: FUNCTION; Schema: feature; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION feature.uuid_generate_v7() RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    raw bytea;
BEGIN
    -- 난수 16바이트의 상위 6바이트를 unix-ms(빅엔디안 하위 6바이트)로 교체.
    raw := overlay(
        uuid_send(x_extension.gen_random_uuid())
        PLACING substring(
            int8send((extract(epoch FROM clock_timestamp()) * 1000)::bigint)
            FROM 3 FOR 6
        )
        FROM 1 FOR 6
    );
    -- version 7: byte 6 상위 nibble = 0111 (0x70).
    raw := set_byte(raw, 6, (get_byte(raw, 6) & 15) | 112);
    -- variant RFC: byte 8 상위 2비트 = 10.
    raw := set_byte(raw, 8, (get_byte(raw, 8) & 63) | 128);
    RETURN encode(raw, 'hex')::uuid;
END;
$$;


ALTER FUNCTION feature.uuid_generate_v7() OWNER TO ktm_feature_schema_owner;

--
-- Name: validate_feature_base_field_value(); Type: FUNCTION; Schema: feature; Owner: ktm_feature_state_procedure_owner
--

CREATE FUNCTION feature.validate_feature_base_field_value() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_registry ops.feature_override_field_paths%ROWTYPE;
    v_feature_kind text;
    v_source_hash text;
BEGIN
    SELECT * INTO v_registry
      FROM ops.feature_override_field_paths
     WHERE field_path = NEW.field_path;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown provider base field path %', NEW.field_path
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_base_field_path';
    END IF;
    SELECT kind INTO v_feature_kind
      FROM feature.features
     WHERE feature_id = NEW.feature_id
       AND feature_uuid = NEW.feature_uuid;
    IF NOT FOUND OR (v_registry.feature_kind <> '*' AND v_registry.feature_kind <> v_feature_kind) THEN
        RAISE EXCEPTION 'base field path % does not apply to Feature', NEW.field_path
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_base_field_target';
    END IF;
    SELECT record.raw_payload_hash INTO v_source_hash
      FROM provider_sync.provider_datasets AS dataset
      JOIN provider_sync.source_entities AS entity
        ON entity.provider_dataset_id = dataset.provider_dataset_id
      JOIN provider_sync.source_records AS record
        ON record.source_entity_key = entity.source_entity_key
      JOIN provider_sync.source_entity_heads AS head
        ON head.source_entity_key = entity.source_entity_key
       AND head.current_source_record_key = record.source_record_key
     WHERE dataset.provider_dataset_id = NEW.provider_dataset_id
       AND entity.source_entity_key = NEW.source_entity_key
       AND record.source_record_key = NEW.source_record_key;
    IF v_source_hash IS NULL OR v_source_hash IS DISTINCT FROM NEW.source_raw_payload_hash THEN
        RAISE EXCEPTION 'base field requires the current canonical source record'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_base_field_source';
    END IF;
    IF v_registry.value_kind = 'geometry' THEN
        IF NOT (
            (NEW.value_json = 'null'::jsonb AND v_registry.allows_null
             AND NEW.value_geometry IS NULL)
            OR (
                NEW.value_json IS NULL AND NEW.value_geometry IS NOT NULL
                AND x_extension.st_srid(NEW.value_geometry) = 4326
                AND upper(x_extension.st_geometrytype(NEW.value_geometry))
                    = 'ST_' || v_registry.geometry_type
            )
        ) THEN
            RAISE EXCEPTION 'base geometry does not match registry type'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_base_field_value';
        END IF;
    ELSIF NEW.value_geometry IS NOT NULL
       OR NEW.value_json IS NULL
       OR (NOT v_registry.allows_null AND NEW.value_json = 'null'::jsonb)
       OR (NEW.value_json <> 'null'::jsonb AND (
              (v_registry.value_kind = 'text' AND jsonb_typeof(NEW.value_json) <> 'string')
           OR (v_registry.value_kind = 'uuid' AND jsonb_typeof(NEW.value_json) <> 'string')
           OR (v_registry.value_kind = 'date' AND jsonb_typeof(NEW.value_json) <> 'string')
           OR (v_registry.value_kind = 'timestamptz' AND jsonb_typeof(NEW.value_json) <> 'string')
           OR (v_registry.value_kind = 'integer' AND jsonb_typeof(NEW.value_json) <> 'number')
           OR (v_registry.value_kind = 'numeric' AND jsonb_typeof(NEW.value_json) <> 'number')
           OR (v_registry.value_kind = 'boolean' AND jsonb_typeof(NEW.value_json) <> 'boolean')
           OR (v_registry.value_kind = 'json_object' AND jsonb_typeof(NEW.value_json) <> 'object')
           OR (v_registry.value_kind IN ('json_array', 'text_array') AND jsonb_typeof(NEW.value_json) <> 'array')
       )) THEN
        RAISE EXCEPTION 'base JSON value does not match registry type'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_base_field_value';
    END IF;
    IF v_registry.value_kind = 'text_array' AND NEW.value_json <> 'null'::jsonb AND EXISTS (
        SELECT 1 FROM jsonb_array_elements(NEW.value_json) AS element
        WHERE jsonb_typeof(element) <> 'string'
    ) THEN
        RAISE EXCEPTION 'base text array contains a non-string value'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_base_field_value';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION feature.validate_feature_base_field_value() OWNER TO ktm_feature_state_procedure_owner;

--
-- Name: validate_feature_override_value(); Type: FUNCTION; Schema: feature; Owner: ktm_feature_state_procedure_owner
--

CREATE FUNCTION feature.validate_feature_override_value() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_registry ops.feature_override_field_paths%ROWTYPE;
    v_feature_kind text;
BEGIN
    -- Lifecycle is owned by the ADR-090 state procedures.  It deliberately
    -- remains outside the generic field path registry and materializer.
    IF NEW.field_path IN ('lifecycle_state', 'status') THEN
        RETURN NEW;
    END IF;
    SELECT * INTO v_registry
      FROM ops.feature_override_field_paths
     WHERE field_path = NEW.field_path;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown feature override field path %', NEW.field_path
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_field_path';
    END IF;
    SELECT kind INTO v_feature_kind
      FROM feature.features
     WHERE feature_id = NEW.feature_id;
    IF NOT FOUND OR (v_registry.feature_kind <> '*' AND v_registry.feature_kind <> v_feature_kind) THEN
        RAISE EXCEPTION 'override field path % does not apply to Feature', NEW.field_path
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_field_target';
    END IF;
    IF v_registry.value_kind = 'geometry' THEN
        IF NOT (
            (NEW.override_value = 'null'::jsonb AND v_registry.allows_null
             AND NEW.value_geometry IS NULL)
            OR (
                NEW.override_value IS NULL AND NEW.value_geometry IS NOT NULL
                AND x_extension.st_srid(NEW.value_geometry) = 4326
                AND upper(x_extension.st_geometrytype(NEW.value_geometry))
                    = 'ST_' || v_registry.geometry_type
            )
        ) THEN
            RAISE EXCEPTION 'override geometry does not match registry type'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_value';
        END IF;
    ELSIF NEW.value_geometry IS NOT NULL
       OR NEW.override_value IS NULL
       OR (NOT v_registry.allows_null AND NEW.override_value = 'null'::jsonb)
       OR (NEW.override_value <> 'null'::jsonb AND (
              (v_registry.value_kind = 'text' AND jsonb_typeof(NEW.override_value) <> 'string')
           OR (v_registry.value_kind = 'uuid' AND jsonb_typeof(NEW.override_value) <> 'string')
           OR (v_registry.value_kind = 'date' AND jsonb_typeof(NEW.override_value) <> 'string')
           OR (v_registry.value_kind = 'timestamptz' AND jsonb_typeof(NEW.override_value) <> 'string')
           OR (v_registry.value_kind = 'integer' AND jsonb_typeof(NEW.override_value) <> 'number')
           OR (v_registry.value_kind = 'numeric' AND jsonb_typeof(NEW.override_value) <> 'number')
           OR (v_registry.value_kind = 'boolean' AND jsonb_typeof(NEW.override_value) <> 'boolean')
           OR (v_registry.value_kind = 'json_object' AND jsonb_typeof(NEW.override_value) <> 'object')
           OR (v_registry.value_kind IN ('json_array', 'text_array') AND jsonb_typeof(NEW.override_value) <> 'array')
       )) THEN
        RAISE EXCEPTION 'override JSON value does not match registry type'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_value';
    END IF;
    IF v_registry.value_kind = 'text_array' AND NEW.override_value <> 'null'::jsonb AND EXISTS (
        SELECT 1 FROM jsonb_array_elements(NEW.override_value) AS element
        WHERE jsonb_typeof(element) <> 'string'
    ) THEN
        RAISE EXCEPTION 'override text array contains a non-string value'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_value';
    END IF;
    IF NOT v_registry.operator_writable AND NEW.status = 'active' THEN
        RAISE EXCEPTION 'field path % cannot be overridden by an operator', NEW.field_path
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_override_operator_policy';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION feature.validate_feature_override_value() OWNER TO ktm_feature_state_procedure_owner;

--
-- Name: validate_theme_candidate_merge_target(); Type: FUNCTION; Schema: feature; Owner: ktm_curation_audit_writer
--

CREATE FUNCTION feature.validate_theme_candidate_merge_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'feature'
    AS $$
BEGIN
  IF NEW.disposition = 'merged' THEN
    IF NEW.merged_into_candidate_id = NEW.candidate_id OR NOT EXISTS (
      SELECT 1
      FROM feature.theme_feature_candidates AS winner
      WHERE winner.candidate_id = NEW.merged_into_candidate_id
        AND winner.rule_id = NEW.rule_id
        AND winner.source_entity_key = NEW.source_entity_key
        AND winner.disposition = 'active'
        AND winner.merged_into_candidate_id IS NULL
      FOR SHARE
    ) THEN
      RAISE EXCEPTION 'merged candidate requires an active same-identity winner'
        USING ERRCODE = '23514', CONSTRAINT = 'ck_theme_feature_candidate_merge_target';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION feature.validate_theme_candidate_merge_target() OWNER TO ktm_curation_audit_writer;

--
-- Name: write_feature_state_transition(); Type: FUNCTION; Schema: feature; Owner: ktm_feature_audit_writer
--

CREATE FUNCTION feature.write_feature_state_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_context_text text;
    v_context jsonb;
    v_state_definer text;
BEGIN
    IF TG_OP = 'UPDATE'
       AND OLD.lifecycle_state IS NOT DISTINCT FROM NEW.lifecycle_state
       AND OLD.publication_state IS NOT DISTINCT FROM NEW.publication_state
       AND OLD.quality_state IS NOT DISTINCT FROM NEW.quality_state THEN
        RETURN NULL;
    END IF;

    v_context_text := current_setting('feature.state_transition_context', true);
    v_state_definer := current_setting('feature.state_procedure_definer', true);
    IF v_context_text IS NULL
       OR v_state_definer <> 'ktm_feature_state_procedure_owner'
       OR current_user <> 'ktm_feature_audit_writer' THEN
        -- schema/migration owner는 runtime trust boundary 밖이다. existing DDL
        -- migration과 fixture seeding은 이 privileged identity로만 direct write를
        -- 수행할 수 있고, application runtime login은 아래 privilege fence에서
        -- 이 분기에 도달하기 전에 거부된다.
        IF EXISTS (
            SELECT 1
            FROM pg_catalog.pg_roles AS role_row
            WHERE role_row.rolname = session_user
              AND role_row.rolsuper
        ) THEN
            RETURN NULL;
        END IF;
        RAISE EXCEPTION 'feature state mutation requires the state procedure context'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_state_transition_context';
    END IF;
    v_context := v_context_text::jsonb;
    IF jsonb_typeof(v_context) IS DISTINCT FROM 'object'
       OR (v_context ->> 'transition_kind') NOT IN (
            'initial', 'legacy_backfill', 'provider_sync', 'admin', 'user_request',
            'merge', 'quality_validation', 'system'
       )
       OR coalesce(btrim(v_context ->> 'reason_code'), '') = ''
       OR coalesce(btrim(v_context ->> 'principal'), '') = '' THEN
        RAISE EXCEPTION 'feature state mutation has malformed context'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_state_transition_context';
    END IF;

    IF TG_OP = 'INSERT' AND (v_context ->> 'transition_kind') NOT IN (
        'initial', 'legacy_backfill', 'provider_sync'
    ) THEN
        RAISE EXCEPTION 'feature insert needs initial or provider-sync state transition kind'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_state_transition_kind';
    END IF;
    IF TG_OP = 'UPDATE' AND (v_context ->> 'transition_kind') IN ('initial', 'legacy_backfill') THEN
        RAISE EXCEPTION 'feature update cannot use initial state transition kind'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_feature_state_transition_kind';
    END IF;

    INSERT INTO feature.feature_state_transitions (
        feature_id, feature_uuid,
        from_lifecycle_state, from_publication_state, from_quality_state,
        to_lifecycle_state, to_publication_state, to_quality_state,
        transition_kind, reason_code, principal, causation_ref,
        provider_dataset_id, source_entity_key, source_record_key, provider_evidence,
        occurred_at,
        row_revision, invoker_role, state_procedure_definer, audit_writer_definer
    ) VALUES (
        NEW.feature_id, NEW.feature_uuid,
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.lifecycle_state END,
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.publication_state END,
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.quality_state END,
        NEW.lifecycle_state, NEW.publication_state, NEW.quality_state,
        v_context ->> 'transition_kind', v_context ->> 'reason_code',
        v_context ->> 'principal', v_context ->> 'causation_ref',
        CASE WHEN v_context ->> 'transition_kind' = 'provider_sync'
             THEN (v_context ->> 'provider_dataset_id')::bigint END,
        CASE WHEN v_context ->> 'transition_kind' = 'provider_sync'
             THEN v_context ->> 'source_entity_key' END,
        CASE WHEN v_context ->> 'transition_kind' = 'provider_sync'
             THEN v_context ->> 'source_record_key' END,
        CASE WHEN v_context ->> 'transition_kind' = 'provider_sync'
             THEN v_context -> 'provider_evidence' END,
        clock_timestamp(),
        NEW.row_revision, session_user::text, v_state_definer, current_user::text
    );
    RETURN NULL;
END;
$$;


ALTER FUNCTION feature.write_feature_state_transition() OWNER TO ktm_feature_audit_writer;

--
-- Name: append_provider_feature_attempt_event_command(text, bigint, text, text, integer, text, jsonb); Type: PROCEDURE; Schema: ops; Owner: ktm_curation_command_owner
--

CREATE PROCEDURE ops.append_provider_feature_attempt_event_command(IN p_dagster_run_id text, IN p_provider_dataset_id bigint, IN p_sync_scope text, IN p_operation_key text, IN p_attempt_number integer, IN p_outcome text, IN p_error jsonb, OUT o_event_id uuid, OUT o_job_id uuid, OUT o_import_job_dataset_id uuid, OUT o_stage text, OUT o_level text, OUT o_code text, OUT o_message text, OUT o_payload jsonb, OUT o_occurred_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
  IF NOT pg_has_role(session_user, 'ktm_curation_provider_executor', 'member')
     OR pg_has_role(session_user, 'ktm_curation_admin_executor', 'member') THEN
    RAISE EXCEPTION 'provider attempt event requires provider executor'
      USING ERRCODE = '42501';
  END IF;
  IF p_attempt_number < 1 OR p_outcome NOT IN ('failed','retryable_failure')
     OR jsonb_typeof(p_error) <> 'object' THEN
    RAISE EXCEPTION 'invalid provider attempt event input'
      USING ERRCODE = '22023';
  END IF;
  INSERT INTO ops.import_job_events (
    job_id, import_job_dataset_id, stage, level, code, message, payload
  )
  SELECT child.job_id, member.import_job_dataset_id, child.current_stage,
         'error', 'feature_operation.attempt',
         'provider feature operation attempt recorded',
         jsonb_build_object(
           'attempt_number', p_attempt_number,
           'outcome', p_outcome,
           'error', p_error,
           'provider_dataset_id', member.provider_dataset_id,
           'sync_scope', member.sync_scope,
           'operation_key', member.operation_key
         )
  FROM ops.import_jobs AS root
  JOIN ops.import_jobs AS child
    ON child.parent_job_id = root.job_id
   AND child.kind = 'provider_feature_load'
  JOIN ops.import_job_datasets AS member ON member.job_id = child.job_id
  WHERE root.kind = 'provider_feature_load_run'
    AND root.dagster_run_id = p_dagster_run_id
    AND root.quarantined_at IS NULL AND child.quarantined_at IS NULL
    AND member.provider_dataset_id = p_provider_dataset_id
    AND member.sync_scope = p_sync_scope
    AND member.operation_key = p_operation_key
  RETURNING event_id, job_id, import_job_dataset_id, stage, level, code,
            message, payload, occurred_at
  INTO STRICT o_event_id, o_job_id, o_import_job_dataset_id, o_stage, o_level,
              o_code, o_message, o_payload, o_occurred_at;
END
$$;


ALTER PROCEDURE ops.append_provider_feature_attempt_event_command(IN p_dagster_run_id text, IN p_provider_dataset_id bigint, IN p_sync_scope text, IN p_operation_key text, IN p_attempt_number integer, IN p_outcome text, IN p_error jsonb, OUT o_event_id uuid, OUT o_job_id uuid, OUT o_import_job_dataset_id uuid, OUT o_stage text, OUT o_level text, OUT o_code text, OUT o_message text, OUT o_payload jsonb, OUT o_occurred_at timestamp with time zone) OWNER TO ktm_curation_command_owner;

--
-- Name: assert_feature_update_job_pair(uuid); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.assert_feature_update_job_pair(candidate_job_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
        DECLARE job_kind text; job_quarantined_at timestamptz;
        BEGIN
            SELECT job.kind, job.quarantined_at
              INTO job_kind, job_quarantined_at
            FROM ops.import_jobs AS job
            WHERE job.job_id = candidate_job_id;
            IF NOT FOUND
               OR job_kind IS DISTINCT FROM 'feature_update_request'
               OR job_quarantined_at IS NOT NULL THEN
                RETURN;
            END IF;

            PERFORM 1
            FROM ops.feature_update_requests AS request
            WHERE request.job_id = candidate_job_id;
            IF NOT FOUND THEN
                RAISE EXCEPTION
                    'non-quarantined canonical feature update job must have exactly one request: %',
                    candidate_job_id
                    USING ERRCODE = '23514',
                        CONSTRAINT = 'ck_import_jobs_feature_update_pair';
            END IF;
        END;
        $$;


ALTER FUNCTION ops.assert_feature_update_job_pair(candidate_job_id uuid) OWNER TO ktm_feature_schema_owner;

--
-- Name: assign_cache_target_outbox_relay_order(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.assign_cache_target_outbox_relay_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
        BEGIN
          PERFORM 1
          FROM ops.poi_cache_target_streams AS stream
          WHERE stream.external_system = NEW.external_system
          FOR UPDATE OF stream;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'cache target stream does not exist'
              USING ERRCODE = '23503';
          END IF;
          NEW.relay_order := nextval(
            'ops.poi_cache_target_outbox_relay_order_seq'::regclass
          );
          RETURN NEW;
        END;
        $$;


ALTER FUNCTION ops.assign_cache_target_outbox_relay_order() OWNER TO ktm_feature_schema_owner;

--
-- Name: bump_import_job_event_clock(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.bump_import_job_event_clock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
          INSERT INTO ops.import_job_event_clock AS clock (
            clock_id, revision, updated_at
          ) VALUES (
            TRUE, 1, clock_timestamp()
          )
          ON CONFLICT (clock_id) DO UPDATE
             SET revision = clock.revision + 1,
                 updated_at = clock_timestamp();
          RETURN NULL;
        END;
        $$;


ALTER FUNCTION ops.bump_import_job_event_clock() OWNER TO ktm_feature_schema_owner;

--
-- Name: bump_ops_live_topic_revision(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.bump_ops_live_topic_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
          IF TG_NARGS <> 1 OR btrim(TG_ARGV[0]) = '' THEN
            RAISE EXCEPTION 'ops live revision trigger requires one topic argument';
          END IF;
          INSERT INTO ops.ops_live_topic_revisions AS live_revision (
            topic,
            revision,
            updated_at
          )
          VALUES (TG_ARGV[0], 1, clock_timestamp())
          ON CONFLICT (topic) DO UPDATE
          SET revision = live_revision.revision + 1,
              updated_at = clock_timestamp();
          RETURN NULL;
        END;
        $$;


ALTER FUNCTION ops.bump_ops_live_topic_revision() OWNER TO ktm_feature_schema_owner;

--
-- Name: check_feature_operation_parent(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.check_feature_operation_parent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        DECLARE
          parent_kind TEXT;
          parent_run_id TEXT;
          parent_created_at TIMESTAMPTZ;
        BEGIN
          SELECT kind, dagster_run_id, created_at
            INTO parent_kind, parent_run_id, parent_created_at
            FROM ops.import_jobs
           WHERE job_id = NEW.parent_job_id
           FOR KEY SHARE;
          IF NOT FOUND OR parent_kind <> 'provider_feature_load_run'
             OR parent_run_id IS DISTINCT FROM NEW.dagster_run_id
             OR parent_created_at IS DISTINCT FROM NEW.created_at THEN
            RAISE EXCEPTION
              'invalid provider feature operation parent/run/create time'
              USING ERRCODE = '23514';
          END IF;
          RETURN NULL;
        END;
        $$;


ALTER FUNCTION ops.check_feature_operation_parent() OWNER TO ktm_feature_schema_owner;

--
-- Name: enforce_backup_command_execution_transition(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.enforce_backup_command_execution_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
          IF OLD.phase = 'effect_succeeded'
             OR (OLD.phase, NEW.phase) NOT IN (
               ('prepared', 'effect_started'),
               ('effect_started', 'effect_succeeded')
             ) THEN
            RAISE EXCEPTION 'invalid backup command execution transition'
              USING ERRCODE = '55000';
          END IF;
          IF (OLD.command_id, OLD.effect_kind, OLD.effect_token,
              OLD.backup_id, OLD.app_db,
              OLD.dagster_db, OLD.rustfs_volume, OLD.marker_key,
              OLD.input_digest, OLD.prepared_result, OLD.prepared_at)
             IS DISTINCT FROM
             (NEW.command_id, NEW.effect_kind, NEW.effect_token,
              NEW.backup_id, NEW.app_db,
              NEW.dagster_db, NEW.rustfs_volume, NEW.marker_key,
              NEW.input_digest, NEW.prepared_result, NEW.prepared_at) THEN
            RAISE EXCEPTION 'backup command execution identity is immutable'
              USING ERRCODE = '55000';
          END IF;
          RETURN NEW;
        END;
        $$;


ALTER FUNCTION ops.enforce_backup_command_execution_transition() OWNER TO ktm_feature_schema_owner;

--
-- Name: enforce_feature_update_job_pair(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.enforce_feature_update_job_pair() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
        BEGIN
            PERFORM ops.assert_feature_update_job_pair(NEW.job_id);
            RETURN NULL;
        END;
        $$;


ALTER FUNCTION ops.enforce_feature_update_job_pair() OWNER TO ktm_feature_schema_owner;

--
-- Name: enforce_feature_update_request_job_identity(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.enforce_feature_update_request_job_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
        DECLARE linked_kind text; linked_quarantined_at timestamptz;
        BEGIN
            SELECT job.kind, job.quarantined_at
              INTO linked_kind, linked_quarantined_at
            FROM ops.import_jobs AS job
            WHERE job.job_id = NEW.job_id
            FOR KEY SHARE;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'feature update request job does not exist: %', NEW.job_id
                    USING ERRCODE = '23503';
            END IF;
            IF linked_kind IS DISTINCT FROM 'feature_update_request' THEN
                RAISE EXCEPTION
                    'feature update request must link a canonical feature_update_request job'
                    USING ERRCODE = '23514',
                        CONSTRAINT = 'ck_feature_update_request_job_kind';
            END IF;
            IF linked_quarantined_at IS NOT NULL THEN
                RAISE EXCEPTION 'feature update request cannot link a quarantined import job'
                    USING ERRCODE = '23514',
                        CONSTRAINT = 'ck_feature_update_request_job_quarantine';
            END IF;
            RETURN NEW;
        END;
        $$;


ALTER FUNCTION ops.enforce_feature_update_request_job_identity() OWNER TO ktm_feature_schema_owner;

--
-- Name: enforce_offline_upload_command_execution_transition(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.enforce_offline_upload_command_execution_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
          IF OLD.phase = 'effect_succeeded'
             OR (OLD.phase, NEW.phase) NOT IN (
               ('prepared', 'effect_started'),
               ('effect_started', 'effect_succeeded')
             ) THEN
            RAISE EXCEPTION 'invalid offline upload command execution transition'
              USING ERRCODE = '55000';
          END IF;
          IF (OLD.command_id, OLD.effect_kind, OLD.upload_id,
              OLD.storage_backend, OLD.bucket, OLD.storage_key,
              OLD.content_type, OLD.byte_size, OLD.content_sha256,
              OLD.metadata_digest, OLD.load_job_id, OLD.input_digest,
              OLD.prepared_at)
             IS DISTINCT FROM
             (NEW.command_id, NEW.effect_kind, NEW.upload_id,
              NEW.storage_backend, NEW.bucket, NEW.storage_key,
              NEW.content_type, NEW.byte_size, NEW.content_sha256,
              NEW.metadata_digest, NEW.load_job_id, NEW.input_digest,
              NEW.prepared_at) THEN
            RAISE EXCEPTION 'offline upload command execution identity is immutable'
              USING ERRCODE = '55000';
          END IF;
          RETURN NEW;
        END;
        $$;


ALTER FUNCTION ops.enforce_offline_upload_command_execution_transition() OWNER TO ktm_feature_schema_owner;

--
-- Name: ensure_provider_feature_operation_command(text, text, text, jsonb, timestamp with time zone, timestamp with time zone, text); Type: PROCEDURE; Schema: ops; Owner: ktm_curation_command_owner
--

CREATE PROCEDURE ops.ensure_provider_feature_operation_command(IN p_dagster_run_id text, IN p_trigger_kind text, IN p_operation_key text, IN p_memberships jsonb, IN p_created_at timestamp with time zone, IN p_started_at timestamp with time zone, IN p_observed_status text, OUT o_root_job_id uuid, OUT o_inserted boolean, OUT o_changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'provider_sync'
    AS $$
DECLARE
  v_member record;
  v_base_status text;
  v_stage text;
  v_member_count bigint;
  v_distinct_member_count bigint;
BEGIN
  IF NOT pg_has_role(session_user, 'ktm_curation_provider_executor', 'member')
     OR pg_has_role(session_user, 'ktm_curation_admin_executor', 'member') THEN
    RAISE EXCEPTION 'provider operation command requires provider executor'
      USING ERRCODE = '42501';
  END IF;
  IF p_dagster_run_id IS NULL OR btrim(p_dagster_run_id) = ''
     OR p_operation_key IS NULL OR btrim(p_operation_key) = ''
     OR p_trigger_kind NOT IN ('schedule','sensor','manual','retry','system')
     OR p_observed_status NOT IN (
       'QUEUED','NOT_STARTED','MANAGED','STARTING','STARTED','CANCELING'
     )
     OR jsonb_typeof(p_memberships) <> 'array'
     OR jsonb_array_length(p_memberships) = 0 THEN
    RAISE EXCEPTION 'invalid provider operation command input'
      USING ERRCODE = '22023';
  END IF;
  IF p_observed_status IN ('STARTED','CANCELING') AND p_started_at IS NULL THEN
    RAISE EXCEPTION 'running provider operation requires started_at'
      USING ERRCODE = '22023';
  END IF;
  SELECT count(*), count(DISTINCT (member.provider_dataset_id, member.sync_scope, member.operation_key))
  INTO STRICT v_member_count, v_distinct_member_count
  FROM jsonb_to_recordset(p_memberships) AS member(
    provider_dataset_id bigint, sync_scope text, operation_key text
  );
  IF v_member_count <> jsonb_array_length(p_memberships)
     OR v_distinct_member_count <> v_member_count THEN
    RAISE EXCEPTION 'provider operation memberships are not unique'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_memberships) AS member(
      provider_dataset_id bigint, sync_scope text, operation_key text
    )
    WHERE member.operation_key <> p_operation_key
       OR member.sync_scope IS NULL OR btrim(member.sync_scope) = ''
       OR NOT EXISTS (
         SELECT 1
         FROM provider_sync.provider_dataset_operation_scopes AS scope
         JOIN provider_sync.provider_dataset_operations AS operation
           ON operation.provider_dataset_id = scope.provider_dataset_id
          AND operation.operation_key = scope.operation_key
          AND operation.operation_kind = scope.operation_kind
         JOIN provider_sync.provider_datasets AS dataset
           ON dataset.provider_dataset_id = scope.provider_dataset_id
         WHERE scope.provider_dataset_id = member.provider_dataset_id
           AND scope.sync_scope = member.sync_scope
           AND scope.operation_key = member.operation_key
           AND operation.operation_kind = 'refresh'
           AND operation.is_enabled AND dataset.is_active
       )
  ) THEN
    RAISE EXCEPTION 'provider operation membership is not active canonical scope'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_provider_operation_membership';
  END IF;

  v_base_status := CASE WHEN p_observed_status IN (
    'QUEUED','NOT_STARTED','MANAGED','STARTING'
  ) THEN 'queued' ELSE 'running' END;
  v_stage := CASE WHEN v_base_status = 'queued' THEN 'queued' ELSE 'loading' END;
  INSERT INTO ops.import_jobs (
    kind, payload, status, progress, current_stage, dagster_run_id,
    dataset_membership_mode, trigger_kind, operation_key, dagster_run_status,
    created_at, started_at, heartbeat_at
  ) VALUES (
    'provider_feature_load_run', '{}'::jsonb, v_base_status, 0, v_stage,
    p_dagster_run_id, 'root', p_trigger_kind, p_operation_key,
    p_observed_status, p_created_at,
    CASE WHEN v_base_status = 'running' THEN p_started_at ELSE NULL END,
    CASE WHEN v_base_status = 'running' THEN p_started_at ELSE NULL END
  )
  ON CONFLICT (dagster_run_id)
    WHERE kind = 'provider_feature_load_run' AND parent_job_id IS NULL
  DO NOTHING
  RETURNING job_id INTO o_root_job_id;
  o_inserted := FOUND;
  IF NOT o_inserted THEN
    SELECT root.job_id INTO o_root_job_id
    FROM ops.import_jobs AS root
    WHERE root.kind = 'provider_feature_load_run'
      AND root.parent_job_id IS NULL
      AND root.dagster_run_id = p_dagster_run_id
      AND root.quarantined_at IS NULL
    FOR UPDATE;
  END IF;
  IF o_root_job_id IS NULL THEN
    RAISE EXCEPTION 'provider operation root is quarantined or missing'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_provider_operation_root';
  END IF;
  IF o_inserted THEN
    FOR v_member IN
      SELECT member.*
      FROM jsonb_to_recordset(p_memberships) AS member(
        provider_dataset_id bigint, sync_scope text, operation_key text
      )
      ORDER BY member.provider_dataset_id, member.sync_scope, member.operation_key
    LOOP
      WITH child AS (
        INSERT INTO ops.import_jobs (
          kind, parent_job_id, payload, status, progress, current_stage,
          dagster_run_id, dataset_membership_mode, created_at, started_at, heartbeat_at
        ) VALUES (
          'provider_feature_load', o_root_job_id, '{}'::jsonb,
          v_base_status, 0, v_stage, p_dagster_run_id, 'single', p_created_at,
          CASE WHEN v_base_status = 'running' THEN p_started_at ELSE NULL END,
          CASE WHEN v_base_status = 'running' THEN p_started_at ELSE NULL END
        ) RETURNING job_id
      )
      INSERT INTO ops.import_job_datasets (
        job_id, provider_dataset_id, sync_scope, operation_key
      ) SELECT child.job_id, v_member.provider_dataset_id,
               v_member.sync_scope, v_member.operation_key FROM child;
    END LOOP;
  END IF;
  o_changed := o_inserted;
  IF p_observed_status IN ('STARTED','CANCELING') THEN
    UPDATE ops.import_jobs AS root
    SET status = 'running', current_stage = 'loading',
        dagster_run_status = p_observed_status,
        started_at = COALESCE(root.started_at, p_started_at),
        heartbeat_at = COALESCE(p_started_at, root.heartbeat_at)
    WHERE root.job_id = o_root_job_id AND root.kind = 'provider_feature_load_run'
      AND root.status = 'queued' AND root.cancellation_id IS NULL
      AND root.quarantined_at IS NULL;
    o_changed := o_changed OR FOUND;
    IF p_observed_status = 'CANCELING' THEN
      UPDATE ops.import_jobs AS root
      SET dagster_run_status = 'CANCELING',
          heartbeat_at = COALESCE(p_started_at, root.heartbeat_at)
      WHERE root.job_id = o_root_job_id
        AND root.kind = 'provider_feature_load_run'
        AND root.status = 'running'
        AND root.dagster_run_status = 'STARTED'
        AND root.cancellation_id IS NULL
        AND root.quarantined_at IS NULL;
      o_changed := o_changed OR FOUND;
    END IF;
    UPDATE ops.import_jobs AS child
    SET status = 'running', current_stage = 'loading',
        started_at = COALESCE(child.started_at, p_started_at),
        heartbeat_at = COALESCE(p_started_at, child.heartbeat_at)
    WHERE child.parent_job_id = o_root_job_id AND child.kind = 'provider_feature_load'
      AND child.status = 'queued' AND child.cancellation_id IS NULL
      AND child.quarantined_at IS NULL;
    o_changed := o_changed OR FOUND;
  ELSIF p_observed_status = 'STARTING' THEN
    UPDATE ops.import_jobs AS root SET dagster_run_status = 'STARTING'
    WHERE root.job_id = o_root_job_id AND root.kind = 'provider_feature_load_run'
      AND root.status = 'queued'
      AND root.dagster_run_status IN ('QUEUED','NOT_STARTED','MANAGED')
      AND root.quarantined_at IS NULL;
    o_changed := o_changed OR FOUND;
  END IF;
END
$$;


ALTER PROCEDURE ops.ensure_provider_feature_operation_command(IN p_dagster_run_id text, IN p_trigger_kind text, IN p_operation_key text, IN p_memberships jsonb, IN p_created_at timestamp with time zone, IN p_started_at timestamp with time zone, IN p_observed_status text, OUT o_root_job_id uuid, OUT o_inserted boolean, OUT o_changed boolean) OWNER TO ktm_curation_command_owner;

--
-- Name: fill_provider_cancellation_starts_command(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: ktm_curation_command_owner
--

CREATE FUNCTION ops.fill_provider_cancellation_starts_command(p_cancellation_id uuid, p_dagster_run_id text, p_engine_started_at timestamp with time zone) RETURNS TABLE(expected_count bigint, owned_count bigint, updated_job_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
  IF session_user <> 'ktm_feature_api_runtime'
     AND NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_roles AS role
       WHERE role.rolname = session_user AND role.rolsuper
     ) THEN
    RAISE EXCEPTION 'provider cancellation command requires API runtime'
      USING ERRCODE = '42501';
  END IF;
  IF p_engine_started_at IS NULL OR p_dagster_run_id IS NULL OR btrim(p_dagster_run_id) = '' THEN
    RAISE EXCEPTION 'invalid provider cancellation start command'
      USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM ops.pipeline_cancellations AS attempt
    JOIN ops.pipeline_cancellation_runs AS run
      ON run.cancellation_id = attempt.cancellation_id
     AND run.dagster_run_id = p_dagster_run_id
    WHERE attempt.cancellation_id = p_cancellation_id
      AND attempt.status = 'in_progress'
      AND run.result IN ('cancelled','already_terminal')
      AND run.engine_started_at = p_engine_started_at
    FOR UPDATE OF attempt, run
  ) THEN
    RAISE EXCEPTION 'provider cancellation start proof is not current'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_provider_cancellation_start_proof';
  END IF;
  RETURN QUERY
  WITH canonical_jobs AS (
    SELECT job.job_id, job.cancellation_id, job.started_at
    FROM ops.pipeline_cancellation_members AS member
    JOIN ops.import_jobs AS job ON job.job_id = member.job_id
    WHERE member.cancellation_id = p_cancellation_id
      AND member.dagster_run_id = p_dagster_run_id
      AND member.operation_kind IN ('provider_feature_load_run','provider_feature_load')
  ),
  updated AS (
    UPDATE ops.import_jobs AS job
    SET started_at = p_engine_started_at
    FROM canonical_jobs AS candidate
    WHERE job.job_id = candidate.job_id
      AND candidate.cancellation_id = p_cancellation_id
      AND job.cancellation_id = p_cancellation_id
      AND job.started_at IS NULL
    RETURNING job.job_id
  )
  SELECT
    (SELECT count(*) FROM canonical_jobs),
    (SELECT count(*) FROM canonical_jobs WHERE cancellation_id = p_cancellation_id),
    COALESCE((SELECT array_agg(job_id ORDER BY job_id) FROM updated), '{}'::uuid[]);
END
$$;


ALTER FUNCTION ops.fill_provider_cancellation_starts_command(p_cancellation_id uuid, p_dagster_run_id text, p_engine_started_at timestamp with time zone) OWNER TO ktm_curation_command_owner;

--
-- Name: finish_provider_feature_membership_command(uuid, bigint, text, text, boolean, timestamp with time zone); Type: PROCEDURE; Schema: ops; Owner: ktm_curation_command_owner
--

CREATE PROCEDURE ops.finish_provider_feature_membership_command(IN p_root_job_id uuid, IN p_provider_dataset_id bigint, IN p_sync_scope text, IN p_operation_key text, IN p_authoritative_snapshot_complete boolean, IN p_finished_at timestamp with time zone, OUT o_changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
DECLARE
  v_child_job_id uuid;
  v_has_receipt boolean;
BEGIN
  IF NOT pg_has_role(session_user, 'ktm_curation_provider_executor', 'member')
     OR pg_has_role(session_user, 'ktm_curation_admin_executor', 'member') THEN
    RAISE EXCEPTION 'provider membership command requires provider executor'
      USING ERRCODE = '42501';
  END IF;
  IF p_authoritative_snapshot_complete IS NULL THEN
    RAISE EXCEPTION 'provider membership completion kind is required'
      USING ERRCODE = '22023';
  END IF;
  SELECT child.job_id INTO STRICT v_child_job_id
  FROM ops.import_jobs AS child
  JOIN ops.import_job_datasets AS member ON member.job_id = child.job_id
  WHERE child.parent_job_id = p_root_job_id
    AND child.kind = 'provider_feature_load'
    AND member.provider_dataset_id = p_provider_dataset_id
    AND member.sync_scope = p_sync_scope
    AND member.operation_key = p_operation_key
    AND child.cancellation_id IS NULL AND child.quarantined_at IS NULL
  FOR UPDATE OF child;
  SELECT EXISTS (
    SELECT 1 FROM ops.curation_provider_snapshot_receipts AS receipt
    WHERE receipt.source_job_id = v_child_job_id
      AND receipt.root_job_id = p_root_job_id
      AND receipt.provider_dataset_id = p_provider_dataset_id
      AND receipt.sync_scope = p_sync_scope
      AND receipt.operation_key = p_operation_key
  ) INTO STRICT v_has_receipt;
  IF p_authoritative_snapshot_complete IS DISTINCT FROM v_has_receipt THEN
    RAISE EXCEPTION 'provider membership completion does not match its immutable seal'
      USING ERRCODE = '23514', CONSTRAINT = 'ck_tvn40_provider_membership_receipt';
  END IF;
  UPDATE ops.import_jobs AS child
  SET status = 'done', progress = 100, current_stage = 'completed',
      finished_at = COALESCE(child.finished_at, p_finished_at, clock_timestamp()),
      heartbeat_at = clock_timestamp(), error_message = NULL,
      payload = child.payload || jsonb_build_object(
        'authoritative_snapshot_complete', p_authoritative_snapshot_complete
      )
  WHERE child.job_id = v_child_job_id
    AND child.status IN ('queued','running')
    AND child.cancellation_id IS NULL AND child.quarantined_at IS NULL;
  o_changed := FOUND;
  WITH counts AS (
    SELECT count(*)::integer AS total,
           count(*) FILTER (WHERE status = 'done')::integer AS done
    FROM ops.import_jobs AS child
    WHERE child.parent_job_id = p_root_job_id
      AND child.kind = 'provider_feature_load' AND child.quarantined_at IS NULL
  )
  UPDATE ops.import_jobs AS root
  SET progress = CASE WHEN counts.total = 0 THEN 0
    ELSE floor(100.0 * counts.done / counts.total)::integer END
  FROM counts WHERE root.job_id = p_root_job_id AND root.quarantined_at IS NULL;
END
$$;


ALTER PROCEDURE ops.finish_provider_feature_membership_command(IN p_root_job_id uuid, IN p_provider_dataset_id bigint, IN p_sync_scope text, IN p_operation_key text, IN p_authoritative_snapshot_complete boolean, IN p_finished_at timestamp with time zone, OUT o_changed boolean) OWNER TO ktm_curation_command_owner;

--
-- Name: force_poi_cache_target_lock_version(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.force_poi_cache_target_lock_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
        BEGIN
            NEW.lock_version := OLD.lock_version + 1;
            RETURN NEW;
        END;
        $$;


ALTER FUNCTION ops.force_poi_cache_target_lock_version() OWNER TO ktm_feature_schema_owner;

--
-- Name: guard_feature_update_request_mutation(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.guard_feature_update_request_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
        DECLARE linked_status text; linked_cancellation_id uuid;
        BEGIN
            IF TG_OP = 'DELETE' THEN
                RAISE EXCEPTION 'feature update request is append-only: %', OLD.request_id
                    USING ERRCODE = '23514',
                        CONSTRAINT = 'ck_feature_update_request_append_only';
            END IF;
            IF NEW.request_id IS DISTINCT FROM OLD.request_id
               OR NEW.job_id IS DISTINCT FROM OLD.job_id
               OR NEW.scope_type IS DISTINCT FROM OLD.scope_type
               OR NEW.scope IS DISTINCT FROM OLD.scope
               OR NEW.dataset_membership_mode
                  IS DISTINCT FROM OLD.dataset_membership_mode
               OR NEW.update_policy IS DISTINCT FROM OLD.update_policy
               OR NEW.run_mode IS DISTINCT FROM OLD.run_mode
               OR NEW.priority IS DISTINCT FROM OLD.priority
               OR NEW.operator IS DISTINCT FROM OLD.operator
               OR NEW.reason IS DISTINCT FROM OLD.reason
               OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
                RAISE EXCEPTION 'feature update request input/audit identity is immutable: %',
                    OLD.request_id
                    USING ERRCODE = '23514',
                        CONSTRAINT = 'ck_feature_update_request_identity_immutable';
            END IF;
            IF NEW.generation IS DISTINCT FROM OLD.generation
               AND NEW.generation <> OLD.generation + 1 THEN
                RAISE EXCEPTION
                    'feature update request generation must increase by exactly one: %',
                    OLD.request_id
                    USING ERRCODE = '23514',
                        CONSTRAINT = 'ck_feature_update_request_generation';
            END IF;
            IF NEW.matched_scope IS DISTINCT FROM OLD.matched_scope
               OR NEW.generation IS DISTINCT FROM OLD.generation THEN
                SELECT job.status, job.cancellation_id
                  INTO linked_status, linked_cancellation_id
                FROM ops.import_jobs AS job
                WHERE job.job_id = OLD.job_id
                FOR UPDATE;
                IF NOT FOUND
                   OR linked_status NOT IN ('queued', 'running')
                   OR linked_cancellation_id IS NOT NULL THEN
                    RAISE EXCEPTION
                        'feature update request mutable fields require active unmarked job: %',
                        OLD.request_id
                        USING ERRCODE = '23514',
                            CONSTRAINT = 'ck_feature_update_request_mutable_fields';
                END IF;
            END IF;
            RETURN NEW;
        END;
        $$;


ALTER FUNCTION ops.guard_feature_update_request_mutation() OWNER TO ktm_feature_schema_owner;

--
-- Name: guard_import_job_event_clock_mutation(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.guard_import_job_event_clock_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
          IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
            RAISE EXCEPTION 'import job event clock singleton cannot be %', TG_OP
              USING ERRCODE = 'check_violation';
          END IF;
          IF pg_trigger_depth() < 2
             OR NEW.clock_id IS DISTINCT FROM OLD.clock_id
             OR NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
            RAISE EXCEPTION
              'import job event clock is event-trigger-owned: revision % -> %',
              OLD.revision, NEW.revision
              USING ERRCODE = 'check_violation';
          END IF;
          RETURN NEW;
        END;
        $$;


ALTER FUNCTION ops.guard_import_job_event_clock_mutation() OWNER TO ktm_feature_schema_owner;

--
-- Name: is_valid_feature_update_filter_array(text[], integer); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.is_valid_feature_update_filter_array(p_values text[], p_max_items integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
        DECLARE
          text_value text;
          seen_values text[] := ARRAY[]::text[];
          canonical_whitespace text := ' '
            || chr(9) || chr(10) || chr(11) || chr(12) || chr(13)
            || chr(28) || chr(29) || chr(30) || chr(31) || chr(133)
            || chr(160) || chr(5760) || chr(8192) || chr(8193) || chr(8194)
            || chr(8195) || chr(8196) || chr(8197) || chr(8198) || chr(8199)
            || chr(8200) || chr(8201) || chr(8202) || chr(8232) || chr(8233)
            || chr(8239) || chr(8287) || chr(12288);
        BEGIN
          IF p_max_items < 0
             OR COALESCE(array_ndims(p_values), 1) <> 1
             OR cardinality(p_values) > p_max_items
             OR (
               cardinality(p_values) > 0
               AND array_lower(p_values, 1) IS DISTINCT FROM 1
             ) THEN
            RETURN false;
          END IF;
          FOREACH text_value IN ARRAY p_values
          LOOP
            IF text_value IS NULL
               OR text_value <> btrim(text_value, canonical_whitespace)
               OR text_value = ''
               OR char_length(text_value) > 128 THEN
              RETURN false;
            END IF;
            IF text_value = ANY(seen_values) THEN
              RETURN false;
            END IF;
            seen_values := array_append(seen_values, text_value);
          END LOOP;
          RETURN true;
        END;
        $$;


ALTER FUNCTION ops.is_valid_feature_update_filter_array(p_values text[], p_max_items integer) OWNER TO ktm_feature_schema_owner;

--
-- Name: is_valid_feature_update_policy(jsonb); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.is_valid_feature_update_policy(p_policy jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
        DECLARE
          boolean_key text;
        BEGIN
          IF jsonb_typeof(p_policy) IS DISTINCT FROM 'object'
             OR p_policy - ARRAY[
               'mode',
               'include_inactive',
               'force_provider_call',
               'dedup_after_load',
               'consistency_check_after_load',
               'prevent_provider_reactivation'
             ]::text[] <> '{}'::jsonb THEN
            RETURN false;
          END IF;

          IF p_policy ? 'mode'
             AND (
               jsonb_typeof(p_policy->'mode') IS DISTINCT FROM 'string'
               OR p_policy->>'mode' IS DISTINCT FROM 'refresh_existing'
             ) THEN
            RETURN false;
          END IF;

          FOREACH boolean_key IN ARRAY ARRAY[
            'include_inactive',
            'force_provider_call',
            'dedup_after_load',
            'consistency_check_after_load',
            'prevent_provider_reactivation'
          ]::text[]
          LOOP
            IF p_policy ? boolean_key
               AND jsonb_typeof(p_policy->boolean_key) IS DISTINCT FROM 'boolean' THEN
              RETURN false;
            END IF;
          END LOOP;
          RETURN true;
        END;
        $$;


ALTER FUNCTION ops.is_valid_feature_update_policy(p_policy jsonb) OWNER TO ktm_feature_schema_owner;

--
-- Name: is_valid_feature_update_scope(text, jsonb); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.is_valid_feature_update_scope(p_scope_type text, p_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
        BEGIN
          IF p_scope_type <> 'provider_dataset' THEN
            RETURN ops.is_valid_feature_update_scope_0075(p_scope_type, p_scope);
          END IF;
          IF jsonb_typeof(p_scope) IS DISTINCT FROM 'object'
             OR p_scope->>'type' IS DISTINCT FROM p_scope_type
             OR p_scope - ARRAY[
                  'type', 'provider_dataset_id', 'sync_scope', 'operation_key'
                ]::text[] <> '{}'::jsonb
             OR jsonb_typeof(p_scope->'provider_dataset_id') IS DISTINCT FROM 'number'
             OR jsonb_typeof(p_scope->'sync_scope') IS DISTINCT FROM 'string'
             OR jsonb_typeof(p_scope->'operation_key') IS DISTINCT FROM 'string' THEN
            RETURN false;
          END IF;
          IF (p_scope->>'provider_dataset_id')::numeric <= 0
             OR (p_scope->>'provider_dataset_id')::numeric
                <> trunc((p_scope->>'provider_dataset_id')::numeric)
             OR NOT provider_sync.is_valid_provider_dataset_sync_scope(
                  p_scope->>'sync_scope'
                )
             OR p_scope->>'operation_key' = ''
             OR p_scope->>'operation_key' <> btrim(p_scope->>'operation_key')
             OR char_length(p_scope->>'operation_key') > 128 THEN
            RETURN false;
          END IF;
          RETURN true;
        END;
        $$;


ALTER FUNCTION ops.is_valid_feature_update_scope(p_scope_type text, p_scope jsonb) OWNER TO ktm_feature_schema_owner;

--
-- Name: is_valid_feature_update_scope_0052(text, jsonb); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.is_valid_feature_update_scope_0052(p_scope_type text, p_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
        DECLARE
          item jsonb;
          center_value jsonb;
          text_value text;
          seen_values text[] := ARRAY[]::text[];
          canonical_whitespace text := ' '
            || chr(9) || chr(10) || chr(11) || chr(12) || chr(13)
            || chr(28) || chr(29) || chr(30) || chr(31) || chr(133)
            || chr(160) || chr(5760) || chr(8192) || chr(8193) || chr(8194)
            || chr(8195) || chr(8196) || chr(8197) || chr(8198) || chr(8199)
            || chr(8200) || chr(8201) || chr(8202) || chr(8232) || chr(8233)
            || chr(8239) || chr(8287) || chr(12288);
        BEGIN
          IF jsonb_typeof(p_scope) IS DISTINCT FROM 'object'
             OR jsonb_typeof(p_scope->'type') IS DISTINCT FROM 'string'
             OR p_scope->>'type' IS DISTINCT FROM p_scope_type THEN
            RETURN false;
          END IF;

          CASE p_scope_type
            WHEN 'feature_ids' THEN
              IF p_scope - ARRAY['type', 'feature_ids']::text[] <> '{}'::jsonb
                 OR jsonb_typeof(p_scope->'feature_ids') IS DISTINCT FROM 'array' THEN
                RETURN false;
              END IF;
              IF jsonb_array_length(p_scope->'feature_ids') > 1000 THEN
                RETURN false;
              END IF;
              FOR item IN SELECT value FROM jsonb_array_elements(p_scope->'feature_ids')
              LOOP
                IF jsonb_typeof(item) IS DISTINCT FROM 'string' THEN
                  RETURN false;
                END IF;
                text_value := item #>> '{}';
                IF text_value <> btrim(text_value, canonical_whitespace)
                   OR text_value = ''
                   OR char_length(text_value) > 256 THEN
                  RETURN false;
                END IF;
                IF text_value = ANY(seen_values) THEN
                  RETURN false;
                END IF;
                seen_values := array_append(seen_values, text_value);
              END LOOP;
              RETURN true;

            WHEN 'center_radius' THEN
              IF p_scope - ARRAY['type', 'center', 'radius_km']::text[]
                   <> '{}'::jsonb
                 OR jsonb_typeof(p_scope->'center') IS DISTINCT FROM 'object'
                 OR jsonb_typeof(p_scope->'radius_km') IS DISTINCT FROM 'number' THEN
                RETURN false;
              END IF;
              center_value := p_scope->'center';
              IF center_value - ARRAY['lon', 'lat']::text[] <> '{}'::jsonb
                 OR jsonb_typeof(center_value->'lon') IS DISTINCT FROM 'number'
                 OR jsonb_typeof(center_value->'lat') IS DISTINCT FROM 'number' THEN
                RETURN false;
              END IF;
              RETURN (center_value->>'lon')::numeric BETWEEN -180 AND 180
                 AND (center_value->>'lat')::numeric BETWEEN -90 AND 90
                 AND (p_scope->>'radius_km')::numeric > 0
                 AND (p_scope->>'radius_km')::numeric <= 500;

            WHEN 'sigungu_by_radius' THEN
              IF p_scope - ARRAY['type', 'center', 'radius_km', 'match']::text[]
                   <> '{}'::jsonb
                 OR jsonb_typeof(p_scope->'center') IS DISTINCT FROM 'object'
                 OR jsonb_typeof(p_scope->'radius_km') IS DISTINCT FROM 'number'
                 OR jsonb_typeof(p_scope->'match') IS DISTINCT FROM 'string' THEN
                RETURN false;
              END IF;
              center_value := p_scope->'center';
              IF center_value - ARRAY['lon', 'lat']::text[] <> '{}'::jsonb
                 OR jsonb_typeof(center_value->'lon') IS DISTINCT FROM 'number'
                 OR jsonb_typeof(center_value->'lat') IS DISTINCT FROM 'number' THEN
                RETURN false;
              END IF;
              RETURN (center_value->>'lon')::numeric BETWEEN -180 AND 180
                 AND (center_value->>'lat')::numeric BETWEEN -90 AND 90
                 AND (p_scope->>'radius_km')::numeric > 0
                 AND (p_scope->>'radius_km')::numeric <= 500
                 AND p_scope->>'match' = 'intersects';

            WHEN 'bbox' THEN
              IF p_scope - ARRAY[
                   'type', 'min_lon', 'min_lat', 'max_lon', 'max_lat'
                 ]::text[] <> '{}'::jsonb
                 OR jsonb_typeof(p_scope->'min_lon') IS DISTINCT FROM 'number'
                 OR jsonb_typeof(p_scope->'min_lat') IS DISTINCT FROM 'number'
                 OR jsonb_typeof(p_scope->'max_lon') IS DISTINCT FROM 'number'
                 OR jsonb_typeof(p_scope->'max_lat') IS DISTINCT FROM 'number' THEN
                RETURN false;
              END IF;
              RETURN (p_scope->>'min_lon')::numeric BETWEEN -180 AND 180
                 AND (p_scope->>'max_lon')::numeric BETWEEN -180 AND 180
                 AND (p_scope->>'min_lat')::numeric BETWEEN -90 AND 90
                 AND (p_scope->>'max_lat')::numeric BETWEEN -90 AND 90
                 AND (p_scope->>'min_lon')::numeric <= (p_scope->>'max_lon')::numeric
                 AND (p_scope->>'min_lat')::numeric <= (p_scope->>'max_lat')::numeric;

            WHEN 'provider_dataset' THEN
              IF p_scope - ARRAY[
                   'type', 'provider', 'dataset_key', 'sync_scope'
                 ]::text[] <> '{}'::jsonb
                 OR jsonb_typeof(p_scope->'provider') IS DISTINCT FROM 'string'
                 OR jsonb_typeof(p_scope->'dataset_key') IS DISTINCT FROM 'string' THEN
                RETURN false;
              END IF;
              IF p_scope->>'provider' <>
                   btrim(p_scope->>'provider', canonical_whitespace)
                 OR p_scope->>'provider' = ''
                 OR char_length(p_scope->>'provider') > 128
                 OR p_scope->>'dataset_key' <>
                      btrim(p_scope->>'dataset_key', canonical_whitespace)
                 OR p_scope->>'dataset_key' = ''
                 OR char_length(p_scope->>'dataset_key') > 128 THEN
                RETURN false;
              END IF;
              IF p_scope ? 'sync_scope' THEN
                IF jsonb_typeof(p_scope->'sync_scope') IS DISTINCT FROM 'string'
                   OR p_scope->>'sync_scope' <>
                        btrim(p_scope->>'sync_scope', canonical_whitespace)
                   OR p_scope->>'sync_scope' = ''
                   OR char_length(p_scope->>'sync_scope') > 128 THEN
                  RETURN false;
                END IF;
              END IF;
              RETURN true;

            WHEN 'cache_target_keys' THEN
              IF p_scope - ARRAY[
                   'type', 'external_system', 'target_keys', 'radius_km', 'scope_mode'
                 ]::text[] <> '{}'::jsonb
                 OR jsonb_typeof(p_scope->'external_system') IS DISTINCT FROM 'string'
                 OR jsonb_typeof(p_scope->'target_keys') IS DISTINCT FROM 'array'
                 OR jsonb_typeof(p_scope->'scope_mode') IS DISTINCT FROM 'string' THEN
                RETURN false;
              END IF;
              IF jsonb_array_length(p_scope->'target_keys') > 500 THEN
                RETURN false;
              END IF;
              IF p_scope->>'external_system' <>
                   btrim(p_scope->>'external_system', canonical_whitespace)
                 OR p_scope->>'external_system' = ''
                 OR char_length(p_scope->>'external_system') > 128
                 OR p_scope->>'scope_mode' NOT IN ('center_radius', 'sigungu_by_radius') THEN
                RETURN false;
              END IF;
              IF p_scope ? 'radius_km' THEN
                IF jsonb_typeof(p_scope->'radius_km') IS DISTINCT FROM 'number' THEN
                  RETURN false;
                END IF;
                IF (p_scope->>'radius_km')::numeric <= 0
                   OR (p_scope->>'radius_km')::numeric > 500 THEN
                  RETURN false;
                END IF;
              END IF;
              FOR item IN SELECT value FROM jsonb_array_elements(p_scope->'target_keys')
              LOOP
                IF jsonb_typeof(item) IS DISTINCT FROM 'string' THEN
                  RETURN false;
                END IF;
                text_value := item #>> '{}';
                IF text_value <> btrim(text_value, canonical_whitespace)
                   OR text_value = ''
                   OR char_length(text_value) > 256 THEN
                  RETURN false;
                END IF;
                IF text_value = ANY(seen_values) THEN
                  RETURN false;
                END IF;
                seen_values := array_append(seen_values, text_value);
              END LOOP;
              RETURN true;
            ELSE
              RETURN false;
          END CASE;
        END;
        $$;


ALTER FUNCTION ops.is_valid_feature_update_scope_0052(p_scope_type text, p_scope jsonb) OWNER TO ktm_feature_schema_owner;

--
-- Name: is_valid_feature_update_scope_0074(text, jsonb); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.is_valid_feature_update_scope_0074(p_scope_type text, p_scope jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
          SELECT ops.is_valid_feature_update_scope_0052(p_scope_type, p_scope)
             AND (
               p_scope_type <> 'cache_target_keys'
               OR char_length(p_scope->>'external_system')
                    <= 112
             )
        $$;


ALTER FUNCTION ops.is_valid_feature_update_scope_0074(p_scope_type text, p_scope jsonb) OWNER TO ktm_feature_schema_owner;

--
-- Name: is_valid_feature_update_scope_0075(text, jsonb); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.is_valid_feature_update_scope_0075(p_scope_type text, p_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
        DECLARE
          item jsonb;
          text_value text;
          seen_values text[] := ARRAY[]::text[];
          canonical_whitespace text := ' '
            || chr(9) || chr(10) || chr(11) || chr(12) || chr(13)
            || chr(28) || chr(29) || chr(30) || chr(31) || chr(133)
            || chr(160) || chr(5760) || chr(8192) || chr(8193) || chr(8194)
            || chr(8195) || chr(8196) || chr(8197) || chr(8198) || chr(8199)
            || chr(8200) || chr(8201) || chr(8202) || chr(8232) || chr(8233)
            || chr(8239) || chr(8287) || chr(12288);
        BEGIN
          IF p_scope_type <> 'cache_target_keys' THEN
            RETURN ops.is_valid_feature_update_scope_0074(p_scope_type, p_scope);
          END IF;
          IF jsonb_typeof(p_scope) IS DISTINCT FROM 'object'
             OR jsonb_typeof(p_scope->'type') IS DISTINCT FROM 'string'
             OR p_scope->>'type' IS DISTINCT FROM p_scope_type
             OR p_scope - ARRAY[
                  'type', 'external_system', 'target_keys', 'radius_km', 'scope_mode'
                ]::text[] <> '{}'::jsonb
             OR jsonb_typeof(p_scope->'external_system') IS DISTINCT FROM 'string'
             OR jsonb_typeof(p_scope->'target_keys') IS DISTINCT FROM 'array'
             OR jsonb_typeof(p_scope->'scope_mode') IS DISTINCT FROM 'string'
             OR jsonb_array_length(p_scope->'target_keys') > 500 THEN
            RETURN false;
          END IF;
          text_value := p_scope->>'external_system';
          IF text_value = ''
             OR char_length(text_value) > 112
             OR text_value <> btrim(text_value, canonical_whitespace)
             OR text_value <> normalize(text_value, NFC)
             OR p_scope->>'scope_mode' NOT IN ('center_radius', 'sigungu_by_radius') THEN
            RETURN false;
          END IF;
          IF p_scope ? 'radius_km' THEN
            IF jsonb_typeof(p_scope->'radius_km') IS DISTINCT FROM 'number'
               OR (p_scope->>'radius_km')::numeric <= 0
               OR (p_scope->>'radius_km')::numeric > 500 THEN
              RETURN false;
            END IF;
          END IF;
          FOR item IN SELECT value FROM jsonb_array_elements(p_scope->'target_keys')
          LOOP
            IF jsonb_typeof(item) IS DISTINCT FROM 'string' THEN
              RETURN false;
            END IF;
            text_value := item #>> '{}';
            IF text_value = ''
               OR char_length(text_value) > 512
               OR text_value <> btrim(text_value, canonical_whitespace)
               OR text_value <> normalize(text_value, NFC)
               OR text_value = ANY(seen_values) THEN
              RETURN false;
            END IF;
            seen_values := array_append(seen_values, text_value);
          END LOOP;
          RETURN true;
        END;
        $$;


ALTER FUNCTION ops.is_valid_feature_update_scope_0075(p_scope_type text, p_scope jsonb) OWNER TO ktm_feature_schema_owner;

--
-- Name: mark_snapshot_material_orphaned(); Type: FUNCTION; Schema: ops; Owner: ktm_feature_schema_owner
--

CREATE FUNCTION ops.mark_snapshot_material_orphaned() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- material row lock과 새 receipt의 FOR SHARE를 먼저 직렬화한다. 마지막 receipt 삭제와
  -- 동시 receipt 발행이 엇갈려 orphan 표시가 stale해지는 것을 막는다.
  PERFORM 1
    FROM ops.poi_cache_target_snapshot_materials AS material
   WHERE material.material_id = OLD.material_id
   FOR UPDATE;

  IF NOT EXISTS (
    SELECT 1
    FROM ops.poi_cache_target_snapshots AS receipt
    WHERE receipt.material_id = OLD.material_id
  ) THEN
    UPDATE ops.poi_cache_target_snapshot_materials AS material
       SET orphaned_at = clock_timestamp()
     WHERE material.material_id = OLD.material_id
       AND material.orphaned_at IS NULL;
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION ops.mark_snapshot_material_orphaned() OWNER TO ktm_feature_schema_owner;

