    AS $$
        BEGIN
            PERFORM provider_sync.assert_feature_update_request_member_available(
                NEW.request_id, NEW.provider_dataset_id, NEW.sync_scope, NEW.operation_key
            );
            RETURN NEW;
        END;
        $$;


